        '    return []\n'
        '\n'
        '\n'
        'def verificar_evidencia(dado: dict, esquema: dict, cwd: str, amostra: int,\n'
        '                        exigencias: list, ensaio: bool, tempo_limite: int,\n'
        '                        rotulo: str, igual: bool = False) -> list:\n'
        '    erros = _evidencia.validar_evidencia(dado, esquema)\n'
        '    if erros:\n'
        '        juntos = "; ".join(erros[:QUANTAS_ACUSACOES_DO_CONTRATO])\n'
        '        return [ROTULADA.format(rotulo, ACUSA_FORA_DO_CONTRATO.format(juntos))]\n'
        '\n'
        '    if _sintetica_do_encadeador(dado):\n'
        '        return []\n'
        '\n'
        '    provado = dado["provado"]\n'
        '    acusacoes = []\n'
        '    if dado["veredito"] == "segue" and not provado:\n'
        '        acusacoes.append(ROTULADA.format(rotulo, ACUSA_SEGUE_SEM_PROVA))\n'
        '    acusacoes += _acusacoes_da_reexecucao(\n'
        '        _amostra_deterministica(dado, provado, amostra),\n'
        '        cwd, tempo_limite, igual, ensaio, rotulo)\n'
        '    for aviso in avisos_do_numero_instavel(provado, rotulo):\n'
        '        print(aviso)\n'
        '    for aviso in avisos_da_contagem_na_afirmacao(provado, rotulo):\n'
        '        print(aviso)\n'
        '    acusacoes += _acusacoes_das_exigencias(provado, exigencias, rotulo)\n'
        '    acusacoes += _acusacoes_do_proximo(dado.get("proximo", ""), rotulo)\n'
        '    acusacoes += _acusacoes_da_pergunta(dado.get("pergunta", ""), rotulo)\n'
        '    return acusacoes\n'
        '\n'
        '\n'
        'def _sem_acento(texto: str) -> str:\n'
        '    decomposto = unicodedata.normalize("NFD", texto.lower())\n'
        '    return "".join(letra for letra in decomposto\n'
        '                   if unicodedata.category(letra) != "Mn")\n'
        '\n'
        '\n'
        'def termos_distintivos(texto: str) -> set:\n'
        '    palavras = FORA_DO_TERMO.split(_sem_acento(texto))\n'
        '    return {palavra for palavra in palavras\n'
        '            if len(palavra) >= TAMANHO_MINIMO_DO_TERMO\n'
        '            and palavra not in BANAIS}\n'
        '\n'
        '\n'
        'def criterios_abertos(corpo: str) -> list:\n'
        '    return CRITERIO_ABERTO.findall(corpo)\n'
        '\n'
        '\n'
        'def criterios_por_bloco(corpo: str) -> dict:\n'
        '    por_bloco, atual = {}, None\n'
        '    for linha in corpo.splitlines():\n'
        '        if CABECALHO_DE_SECAO.match(linha):\n'
        '            de_um_bloco = SECAO_DE_UM_BLOCO.match(linha)\n'
        '            atual = de_um_bloco.group(1) if de_um_bloco else None\n'
        '            if atual is not None:\n'
        '                por_bloco.setdefault(atual, [])\n'
        '        elif atual is not None and (achado :=\n'
        '                                       CRITERIO_ABERTO.match(linha)):\n'
        '            por_bloco[atual].append(achado.group(1))\n'
        '    return por_bloco\n'
        '\n'
        '\n'
        'def _criterios_no_escopo(corpo: str, bloco) -> tuple:\n'
        '    todos = criterios_abertos(corpo)\n'
        '    if not bloco:\n'
        '        return todos, False\n'
        '    por_bloco = criterios_por_bloco(corpo)\n'
        '    if str(bloco) not in por_bloco:\n'
        '        return None, True\n'
        '    do_bloco = por_bloco[str(bloco)]\n'
        '    return do_bloco, True\n'
        '\n'
        '\n'
        'def _declarado_nas_evidencias(arquivos: list) -> tuple:\n'
        '    declarado, acusacoes = set(), []\n'
        '    for arquivo in arquivos:\n'
        '        try:\n'
        '            dado = json.loads(arquivo.read_text(encoding="utf-8"))\n'
        '        except (OSError, ValueError, RecursionError) as erro:\n'
        '            acusacoes.append(ROTULADA.format(\n'
        '                arquivo.name, ACUSA_EVIDENCIA_ILEGIVEL.format(erro)))\n'
        '            continue\n'
        '        if not isinstance(dado, dict):\n'
        '            acusacoes.append(ROTULADA.format(\n'
        '                arquivo.name, ACUSA_EVIDENCIA_ILEGIVEL.format(NAO_E_OBJETO)))\n'
        '            continue\n'
        '        for item in dado.get("provado") or []:\n'
        '            if isinstance(item, dict):\n'
        '                declarado |= termos_distintivos(" ".join(\n'
        '                    str(item.get(campo, "")) for campo in CAMPOS_DA_PROVA))\n'
        '        for campo in CAMPOS_QUE_RESPONDEM:\n'
        '            for item in dado.get(campo) or []:\n'
        '                declarado |= termos_distintivos(str(item))\n'
        '    return declarado, acusacoes\n'
        '\n'
        '\n'
        'def acusacoes_dos_criterios(criterios: list, declarado: set) -> list:\n'
        '    acusacoes = []\n'
        '    for criterio in criterios:\n'
        '        procurados = termos_distintivos(criterio)\n'
        '        faltando = sorted(procurados - declarado)\n'
        '        if procurados and len(faltando) * 2 > len(procurados):\n'
        '            acusacoes.append(ACUSA_CRITERIO_SEM_RESPOSTA.format(\n'
        '                criterio[:LIMITE_DO_CRITERIO],\n'
        '                ", ".join(faltando[:LIMITE_DOS_TERMOS])))\n'
        '    return acusacoes\n'
        '\n'
        '\n'
        'def _corpo_da_issue(de_onde: str) -> str:\n'
        '    if de_onde == ENTRADA_PADRAO:\n'
        '        return sys.stdin.read()\n'
        '    return Path(de_onde).read_text(encoding="utf-8")\n'
        '\n'
        '\n'
        'def respondem_ao_criterio(arquivos: list) -> list:\n'
        '    return [arquivo for arquivo in arquivos\n'
        '            if not NOME_DA_VERIFICACAO.fullmatch(arquivo.name)]\n'
        '\n'
        '\n'
        'def verificar_criterios(alvos: list, de_onde: str, bloco=None) -> int:\n'
        '    for alvo in alvos:\n'
        '        if not alvo.is_dir():\n'
        '            print(ERRO_ALVO_NAO_E_PASTA.format(alvo), file=sys.stderr)\n'
        '            return 2\n'
        '    try:\n'
        '        corpo = _corpo_da_issue(de_onde)\n'
        '    except (OSError, UnicodeDecodeError) as erro:\n'
        '        print(ERRO_CRITERIOS_ILEGIVEIS.format(de_onde, erro), file=sys.stderr)\n'
        '        return 2\n'
        '    criterios, do_escopo = _criterios_no_escopo(corpo, bloco)\n'
        '    if criterios is None:\n'
        '        print(ERRO_BLOCO_FORA_DO_CORPO.format(bloco=bloco, origem=de_onde),\n'
        '              file=sys.stderr)\n'
        '        return 2\n'
        '    if not criterios:\n'
        '        print(RESUMO_SEM_CRITERIO_NO_BLOCO if do_escopo\n'
        '              else RESUMO_SEM_CRITERIO)\n'
        '        return 0\n'
        '    arquivos = [a for alvo in alvos for a in _evidencias_da_pasta(alvo)]\n'
        '    if not arquivos:\n'
        '        print(ERRO_PASTA_SEM_EVIDENCIA.format(\n'
        '            ", ".join(str(alvo) for alvo in alvos)), file=sys.stderr)\n'
        '        return 2\n'
        '    respondentes = respondem_ao_criterio(arquivos)\n'
        '    declarado, acusacoes = _declarado_nas_evidencias(respondentes)\n'
        '    acusacoes += acusacoes_dos_criterios(criterios, declarado)\n'
        '    for acusacao in acusacoes:\n'
        '        print(LINHA_ACUSA.format(acusacao))\n'
        '    if acusacoes:\n'
        '        print(RESUMO_CRITERIOS_ACUSADOS.format(len(acusacoes), len(criterios)))\n'
        '        return 4\n'
        '    print(RESUMO_CRITERIOS_COBERTOS.format(len(criterios),\n'
        '                                          len(respondentes)))\n'
        '    return 0\n'
        '\n'
        '\n'
        'def montar_parser() -> argparse.ArgumentParser:\n'
        '    parser = argparse.ArgumentParser(prog="verificar.py")\n'
        '    sub = parser.add_subparsers(dest="comando", required=True)\n'
        '\n'
        '    def comuns(p):\n'
        '        p.add_argument("alvo")\n'
        '        p.add_argument("--cwd", default=".", help=AJUDA_CWD)\n'
        '        p.add_argument("--amostra", type=int, default=0, help=AJUDA_AMOSTRA)\n'
        '        p.add_argument("--exigir", action="append", default=[],\n'
        '                       help=AJUDA_EXIGIR)\n'
        '        p.add_argument("--ensaio", action="store_true", help=AJUDA_ENSAIO)\n'
        '        p.add_argument("--igual", action="store_true", help=AJUDA_IGUAL)\n'
        '        p.add_argument("--tempo-limite", type=int,\n'
        '                       default=TEMPO_LIMITE_PADRAO, help=AJUDA_TEMPO_LIMITE)\n'
        '\n'
        '    comuns(sub.add_parser("evidencia", help=AJUDA_MODO_EVIDENCIA))\n'
        '    comuns(sub.add_parser("trabalho", help=AJUDA_MODO_TRABALHO))\n'
        '\n'
        '    criterios = sub.add_parser("criterios", help=AJUDA_MODO_CRITERIOS)\n'
        '    criterios.add_argument("alvo", nargs="+")\n'
        '    criterios.add_argument("--criterios", required=True, help=AJUDA_CRITERIOS)\n'
        '    criterios.add_argument("--bloco", help=AJUDA_BLOCO)\n'
        '    return parser\n'
        '\n'
        '\n'
        'def _evidencias_da_pasta(alvo: Path) -> list:\n'
        '    arquivos = sorted(a for a in alvo.iterdir()\n'
        '                      if NOME_DE_EVIDENCIA.fullmatch(a.name))\n'
        '    for fora in sorted(alvo.iterdir()):\n'
        '        if not NOME_DE_EVIDENCIA.fullmatch(fora.name):\n'
        '            print(LINHA_IGNORADO.format(fora.name))\n'
        '    return arquivos\n'
        '\n'
        '\n'
        'def _acusacoes_dos_arquivos(arquivos: list, esquema: dict, args) -> list:\n'
        '    acusacoes = []\n'
        '    for arquivo in arquivos:\n'
        '        if not arquivo.is_file():\n'
        '            acusacoes.append(ROTULADA.format(arquivo.name,\n'
        '                                             ACUSA_NAO_E_ARQUIVO_COMUM))\n'
        '            continue\n'
        '        try:\n'
        '            dado = json.loads(arquivo.read_text(encoding="utf-8"))\n'
        '        except (OSError, ValueError, RecursionError) as erro:\n'
        '            acusacoes.append(ROTULADA.format(\n'
        '                arquivo.name, ACUSA_EVIDENCIA_ILEGIVEL.format(erro)))\n'
        '            continue\n'
        '        acusacoes += verificar_evidencia(dado, esquema, args.cwd, args.amostra,\n'
        '                                         args.exigir, args.ensaio,\n'
        '                                         args.tempo_limite, arquivo.name,\n'
        '                                         args.igual)\n'
        '    return acusacoes\n'
        '\n'
        '\n'
        'def _dizer_o_veredito(acusacoes: list, quantas_evidencias: int,\n'
        '                      ensaio: bool) -> int:\n'
        '    if acusacoes:\n'
        '        for acusacao in acusacoes:\n'
        '            print(LINHA_ACUSA.format(acusacao))\n'
        '        print(RESUMO_ACUSACOES.format(len(acusacoes), quantas_evidencias))\n'
        '        return 4\n'
        '    print(RESUMO_TUDO_BATE.format(quantas_evidencias,\n'
        '                                  MODO_ENSAIO if ensaio else MODO_REEXECUTADO))\n'
        '    return 0\n'
        '\n'
        '\n'
        'def main(argv) -> int:\n'
        '    args = montar_parser().parse_args(argv)\n'
        '    if args.comando == "criterios":\n'
        '        return verificar_criterios([Path(a) for a in args.alvo],\n'
        '                                   args.criterios, args.bloco)\n'
        '    if args.tempo_limite < 1:\n'
        '        print(ERRO_TEMPO_LIMITE_INVALIDO.format(args.tempo_limite),\n'
        '              file=sys.stderr)\n'
        '        return 2\n'
        '    esquema = _evidencia.carregar_esquema()\n'
        '\n'
        '    if not Path(args.cwd).is_dir():\n'
        '        print(ERRO_CWD_INEXISTENTE.format(args.cwd), file=sys.stderr)\n'
        '        return 2\n'
        '    if args.comando == "trabalho" and args.exigir:\n'
        '        print(ERRO_EXIGIR_POR_ETAPA, file=sys.stderr)\n'
        '        return 2\n'
        '\n'
        '    alvo = Path(args.alvo)\n'
        '    if args.comando == "evidencia":\n'
        '        if not alvo.is_file():\n'
        '            print(ERRO_ALVO_INEXISTENTE.format(alvo), file=sys.stderr)\n'
        '            return 2\n'
        '        arquivos = [alvo]\n'
        '    else:\n'
        '        if not alvo.is_dir():\n'
        '            print(ERRO_ALVO_NAO_E_PASTA.format(alvo), file=sys.stderr)\n'
        '            return 2\n'
        '        arquivos = _evidencias_da_pasta(alvo)\n'
        '        if not arquivos:\n'
        '            print(ERRO_PASTA_SEM_EVIDENCIA.format(alvo), file=sys.stderr)\n'
        '            return 2\n'
        '\n'
        '    return _dizer_o_veredito(_acusacoes_dos_arquivos(arquivos, esquema, args),\n'
        '                             len(arquivos), args.ensaio)\n'
        '\n'
        '\n'
        'def _base(**troca):\n'
        '    dado = {\n'
        '        "etapa": "fantoche", "trabalho": "issue-0",\n'
        '        "quando": "2026-08-16T12:00:00-03:00", "veredito": "segue",\n'
        '        "provado": [{"afirmacao": "o eco responde",\n'
        '                     "comando": "echo ola", "saida": "ola"}],\n'
        '        "suposto": [], "faltas": [],\n'
        '        "ciclo": {"i": 1, "teto": 3},\n'
        '    }\n'
        '    dado.update(troca)\n'
        '    return dado\n'
        '\n'
        '\n'
        'BATE = [\n'
        '    ("provado honesto re-executa igual", _base(), []),\n'
        '    ("sintético desligada é pulado (skip simétrico)", _base(\n'
        '        provado=[], origem="encadeador", motivo="desligada",\n'
        '        faltas=["etapa desligada no roteiro"]), []),\n'
        '    ("para com proximo decente e sem prova", _base(\n'
        '        veredito="para", provado=[],\n'
        '        faltas=["faltou a paginação pedida"],\n'
        '        proximo="Implemente a paginação pedida na issue e prove com a "\n'
        '                "página 2 diferente da 1."), []),\n'
        '    ("pergunta com a recomendação primeiro", _base(\n'
        '        veredito="pergunta",\n'
        '        pergunta="Recomendo A porque custa um comando. Sigo com A?"), []),\n'
        '    ("pergunta com recomendação terminada em exclamação", _base(\n'
        '        veredito="pergunta",\n'
        '        pergunta="Recomendo A porque custa um comando! Sigo com A?"), []),\n'
        '    ("contagem sem lastro na afirmação avisa, não acusa", _base(provado=[\n'
        '        {"afirmacao": "eram 51 casos no piso", "comando": "echo 59",\n'
        '         "saida": "59"}]), []),\n'
        '    ("exigência presente no provado", _base(), ["echo"]),\n'
        '    ("exigência sem caixa e com espaço a mais", _base(), ["Echo"]),\n'
        '    ("proximo que cita a banalidade no meio de instrução real", _base(\n'
        '        veredito="para",\n'
        '        proximo="Se falhar, tente de novo com o venv ativo e rode o lint "\n'
        '                "antes de reabrir."), []),\n'
        '    ("contraprova negativa com a convenção do || true", _base(provado=[\n'
        '        {"afirmacao": "não há segredo no arquivo",\n'
        '         "comando": "grep -c segredo /dev/null || true", "saida": "0"}]), []),\n'
        '    ("trecho anotado bate contra a saída inteira", _base(provado=[\n'
        '        {"afirmacao": "o meio da saída é o que importa",\n'
        '         "comando": r"printf \'cabeçalho\\nlinha que importa\\nrodapé\\n\'",\n'
        '         "saida": "linha que importa"}]), []),\n'
        '    ("bloco de linhas seguidas bate no meio da saída", _base(provado=[\n'
        '        {"afirmacao": "duas linhas seguidas",\n'
        '         "comando": r"printf \'a\\nb\\nc\\nd\\n\'", "saida": "b\\nc"}]), []),\n'
        '    ("elisão declara o corte e as duas pontas batem", _base(provado=[\n'
        '        {"afirmacao": "começo e fim, com o meio cortado",\n'
        '         "comando": r"printf \'a\\nb\\nc\\nd\\n\'",\n'
        '         "saida": "a\\n(...)\\nd"}]), []),\n'
        ']\n'
        '\n'
        'ACUSA = [\n'
        '    ("saída forjada — o pronto-quando do degrau", _base(provado=[\n'
        '        {"afirmacao": "o eco responde", "comando": "echo ola",\n'
        '         "saida": "adeus"}]), [], "saída diverge"),\n'
        '    ("comando que não roda", _base(provado=[\n'
        '        {"afirmacao": "roda", "comando": "comando-que-nao-existe-xyz 2>/dev/null",\n'
        '         "saida": "ok"}]), [], "falhou (exit"),\n'
        '    ("comando que falha não prova sucesso", _base(provado=[\n'
        '        {"afirmacao": "a validação passa", "comando": "false",\n'
        '         "saida": ""}]), [], "falhou (exit"),\n'
        '    ("segue sem prova nenhuma (regra 2)", _base(provado=[]), [], "regra 2"),\n'
        '    ("exigência ausente do provado", _base(), ["mcp-sonda"],\n'
        '     "nenhum comando"),\n'
        '    ("exigência citada só na afirmação não vale", _base(provado=[\n'
        '        {"afirmacao": "rodei pytest -q e passou tudo", "comando": "echo ok",\n'
        '         "saida": "ok"}]), ["pytest"], "nenhum comando"),\n'
        '    ("pergunta sem interrogação nenhuma", _base(\n'
        '        veredito="pergunta", pergunta="Diga se sigo com A ou com B"),\n'
        '     [], "sem pergunta"),\n'
        '    ("dois-pontos sem recomendação de verdade", _base(\n'
        '        veredito="pergunta", pergunta="Dúvida: sigo com A ou com B?"),\n'
        '     [], "recomendação"),\n'
        '    ("proximo banal", _base(veredito="para", proximo="Tente de novo."),\n'
        '     [], "nunca \'tente de novo\'"),\n'
        '    ("proximo curto demais", _base(veredito="para", proximo="conserte isto"),\n'
        '     [], "curto demais"),\n'
        '    ("duas perguntas", _base(veredito="pergunta",\n'
        '                             pergunta="Recomendo A. Sigo? Ou paro?"),\n'
        '     [], "mais de uma"),\n'
        '    ("pergunta antes da recomendação", _base(\n'
        '        veredito="pergunta", pergunta="Sigo com A? Recomendo A."),\n'
        '     [], "recomendação primeiro"),\n'
        '    ("evidência fora do contrato", _base(veredito="quase"), [], "fora do contrato"),\n'
        '    ("saída vazia declarada não aceita saída que apareceu", _base(provado=[\n'
        '        {"afirmacao": "não achou nada", "comando": "echo achou",\n'
        '         "saida": ""}]), [], "saída diverge"),\n'
        '    ("contém é por linha inteira: \'ok\' não passa dentro de \'not ok\'",\n'
        '     _base(provado=[{"afirmacao": "passou", "comando": "echo \'not ok\'",\n'
        '                     "saida": "ok"}]), [], "não aparece na saída"),\n'
        '    ("linha declarada que não existe na saída ainda acusa", _base(provado=[\n'
        '        {"afirmacao": "tem a linha", "comando": r"printf \'a\\nb\\n\'",\n'
        '         "saida": "z"}]), [], "não aparece na saída"),\n'
        '    ("linhas certas fora da ordem declarada acusam", _base(provado=[\n'
        '        {"afirmacao": "duas linhas", "comando": r"printf \'a\\nb\\nc\\n\'",\n'
        '         "saida": "c\\na"}]), [], "saída diverge"),\n'
        ']\n'
        '\n'
        '\n'
        'def _cli(argumentos, entrada=None):\n'
        '    return subprocess.run(\n'
        '        [sys.executable, str(Path(__file__).resolve())] + argumentos,\n'
        '        input=entrada, capture_output=True, text=True, timeout=120)\n'
        '\n'
        '\n'
        'def _gravar(pasta, nome, dado):\n'
        '    caminho = Path(pasta) / nome\n'
        '    caminho.parent.mkdir(parents=True, exist_ok=True)\n'
        '    caminho.write_text(json.dumps(dado, ensure_ascii=False), encoding="utf-8")\n'
        '    return caminho\n'
        '\n'
        '\n'
        'def _a_forja_e_acusada_com_exit_4(pasta, caso):\n'
        '    forjado = _gravar(pasta, "forja/01-fantoche-c1.json", _base(provado=[\n'
        '        {"afirmacao": "o eco responde", "comando": "echo ola",\n'
        '         "saida": "adeus"}]))\n'
        '    resposta = _cli(["evidencia", str(forjado)])\n'
        '    caso("forja acusada com exit 4", resposta.returncode == 4\n'
        '         and "saída diverge" in resposta.stdout)\n'
        '    honesto = _gravar(pasta, "forja/02-fantoche-c1.json", _base())\n'
        '    resposta = _cli(["evidencia", str(honesto)])\n'
        '    caso("evidência honesta bate com exit 0", resposta.returncode == 0)\n'
        '\n'
        '\n'
        'def _o_ensaio_nao_executa_nada(pasta, caso):\n'
        '    sentinela = Path(pasta) / "sentinela.txt"\n'
        '    vigiado = _gravar(pasta, "vigia/01-fantoche-c1.json", _base(provado=[\n'
