        'def _comportamento(pasta):\n'
        '    resultados = []\n'
        '\n'
        '    def caso(rotulo, condicao):\n'
        '        resultados.append((rotulo, bool(condicao)))\n'
        '\n'
        '    _a_forja_e_acusada_com_exit_4(pasta, caso)\n'
