        '    _as_fronteiras_de_uso(pasta, caso)\n'
        '    _o_fifo_nao_pendura_nem_cala(pasta, caso)\n'
        '    _a_acusacao_aponta_onde_diverge(caso)\n'
        '    _nome_fora_do_padrao_aparece_como_ignorado(pasta, caso)\n'
        '    _igual_restaura_a_igualdade_estrita(pasta, caso)\n'
        '    _o_aviso_do_grep_so_onde_cabe(pasta, caso)\n'
        '    _a_regua_do_contem(caso)\n'
        '    _o_espaco_no_fim_nao_reprova(caso)\n'
        '    _o_enquadramento_e_distinguido_do_conteudo(caso)\n'
        '    _o_bashismo_bate_no_bash(pasta, caso)\n'
        '    _o_numero_instavel_e_avisado(caso)\n'
        '    _a_contagem_da_afirmacao_e_avisada(caso)\n'
        '    _os_criterios_da_issue_sao_verificados(pasta, caso)\n'
        '    _o_escopo_do_bloco_recorta_a_cobranca(pasta, caso)\n'
        '    return resultados\n'
        '\n'
        '\n'
        'def testar() -> int:\n'
        '    esquema = _evidencia.carregar_esquema()\n'
        '    falhas = []\n'
        '\n'
        '    for rotulo, dado, exigencias in BATE:\n'
        '        achadas = verificar_evidencia(dado, esquema, ".", 0, exigencias,\n'
