        'GLOB_PYTHON = "*.py"\n'
        'GLOB_SKILL = "*/SKILL.md"\n'
        'GLOB_PAGINA = "*.md"\n'
        'BANDEIRA_DE_TESTE = "--testar"\n'
        'MARCAS_DE_RESUMO = ("OK:", "FALHOU:")\n'
        '\n'
        'FRONTMATTER = re.compile(r"^---\\n(.*?)\\n---\\n", re.S)\n'
        'CAMPO_NOME = re.compile(r"^name:\\s*(.+)$", re.M)\n'
        'CAMPO_DESCRICAO = re.compile(r"^description:\\s*(.+)$", re.M)\n'
        'CAMPO_DAS_FERRAMENTAS = re.compile(r"^tools:\\s*\\S", re.M)\n'
        'FORMAS_DE_FUNCAO = (ast.FunctionDef, ast.AsyncFunctionDef)\n'
        'MARCA_DE_TESTE_NO_NOME = "test"\n'
        'MARCA_DA_BANDEIRA_DE_TESTE = "testar"\n'
        'LINHA_DO_CATALOGO = "- {}: {}\\n"\n'
        '\n'
        'MODELO_DA_SIMULACAO = "claude-haiku-4-5-20251001"\n'
        'FERRAMENTAS_DA_SIMULACAO = "Read,Glob,Grep,Write,Bash"\n'
        'TEMPO_DA_SIMULACAO = 900\n'
        'TEMPO_DE_UM_TESTE = 900\n'
        'ARQUIVO_PEDIDO = "tmp/somar.py"\n'
        '\n'
        'TITULO_MEDIR = "O QUE A CAMADA COBRA"\n'
        'TITULO_PROVAR = "O QUE A CAMADA PROVA"\n'
        'TITULO_SIMULAR = "UMA SESSÃO DE VERDADE"\n'
        'LINHA = "  {:<44} {}"\n'
        'LINHA_DE_CASO = "  [{}] {}"\n'
        'SEM_CLAUDE = "  (claude fora do PATH — a simulação não rodou)"\n'
        'SEM_REGRAS = "  (sem nucleo/regras.json — a simulação não tem gabarito)"\n'
        'NUMERO_DESCONHECIDO = "Número que não existe: {}.\\nOs que existem: {}."\n'
        'NUMERO_NAO_MEDIDO = "não medido"\n'
        'FORA_DA_RAIZ = "Rode na raiz do repositório: {} não encontrado aqui."\n'
        '\n'
        'PEDIDO = """Você abriu esta sessão na raiz de um repositório que tem uma camada de\n'
        'instruções para agentes. Leia o que a camada manda ler e faça as duas coisas.\n'
        '\n'
        'PARTE 1 — responda pelo que a camada diz, não pelo que você acha.\n'
        'PARTE 2 — escreva o arquivo {arquivo}: um script que soma os inteiros passados na\n'
        'linha de comando e imprime a soma. Ele precisa ter um `--testar` próprio que sai 0\n'
        'quando passa, e esse teste tem de exercitar o código do próprio arquivo.\n'
        '\n'
        'Sua ÚLTIMA mensagem tem de ser só este JSON, sem cerca de código:\n'
        '{{"onde_abrir": "<em que pasta a sessão se abre e por quê>",\n'
        '  "quantas_regras": <número inteiro de regras numeradas da camada>,\n'
        '  "posso_commitar": "<sim|nao|depende — e em uma frase, por quê>",\n'
        '  "segredo_em_texto_rastreado": "<o que a camada manda escrever no lugar do valor>",\n'
        '  "branch_de_longa_duracao": "<o que a camada manda fazer com ela>",\n'
        '  "o_que_e_pronto": "<quando a camada deixa chamar um trabalho de pronto>"}}"""\n'
        '\n'
        '\n'
        'def corre(comando, tempo=TEMPO_DE_UM_TESTE):\n'
        '    r = subprocess.run(comando, shell=True, capture_output=True, text=True,\n'
        '                       timeout=tempo)\n'
        '    return r.returncode, (r.stdout + r.stderr).strip()\n'
        '\n'
        '\n'
        'def pasta_das_skills(raiz: Path) -> Path:\n'
        '    instalada = raiz / PASTA_DAS_SKILLS\n'
        '    return instalada if instalada.is_dir() else raiz / PASTA_DAS_SKILLS_FONTE\n'
        '\n'
        '\n'
        'PASTAS_DE_SKILL_DA_FERRAMENTA = ("plugins", "skills")\n'
        'ORCAMENTO_DA_LISTAGEM = 8000\n'
        'FORA_DO_ALCANCE = ("a listagem de skills que a ferramenta monta some {} bytes "\n'
        '                   "de {} skill(s) da máquina, contra um orçamento de {} — {}x "\n'
        '                   "acima. Acima do orçamento a ferramenta corta descrição, e "\n'
        '                   "skill sem descrição perde o gatilho. Isto NÃO é do "\n'
        '                   "repositório e não reprova: o catálogo daqui é a linha de "\n'
        '                   "cima. Conte com: find ~/.claude -name SKILL.md")\n'
        'LISTAGEM_NAO_MEDIDA = ("a listagem da máquina não foi medida — não há pasta de "\n'
        '                       "skill da ferramenta neste alcance")\n'
        '\n'
        'TETO_DO_CORPO_DA_SKILL = 10000\n'
        'SKILL_ACIMA_DO_TETO = "{} ({} bytes)"\n'
        'NENHUMA_SKILL_ACIMA = "nenhuma"\n'
        '\n'
        '\n'
        'def skills_da_ferramenta() -> list:\n'
        '    pasta_da_ferramenta = Path.home() / ".claude"\n'
        '    achadas = []\n'
        '    for pasta in PASTAS_DE_SKILL_DA_FERRAMENTA:\n'
        '        alvo = pasta_da_ferramenta / pasta\n'
        '        if alvo.is_dir():\n'
        '            achadas += [p for p in alvo.rglob("SKILL.md") if p.is_file()]\n'
        '    return achadas\n'
        '\n'
        '\n'
        'def listagem_da_ferramenta() -> tuple:\n'
        '    achadas = skills_da_ferramenta()\n'
        '    return sum(len(catalogo_e_corpo(p)[0].encode()) for p in achadas), len(achadas)\n'
        '\n'
        '\n'
        'def anexos_da_skill(skill: Path) -> int:\n'
        '    return sum(len(anexo.read_bytes())\n'
        '               for anexo in sorted(skill.parent.rglob("*"))\n'
        '               if anexo.is_file() and anexo != skill)\n'
        '\n'
        '\n'
        'def catalogo_e_corpo(skill: Path) -> tuple:\n'
        '    texto = skill.read_text(encoding="utf-8", errors="replace")\n'
        '    frente = FRONTMATTER.match(texto)\n'
        '    if not frente:\n'
        '        return "", len(texto.encode())\n'
        '    nome = CAMPO_NOME.search(frente.group(1))\n'
        '    descricao = CAMPO_DESCRICAO.search(frente.group(1))\n'
        '    if not (nome and descricao):\n'
        '        return "", len(texto.encode())\n'
        '    listada = LINHA_DO_CATALOGO.format(nome.group(1).strip(),\n'
        '                                       descricao.group(1).strip())\n'
        '    return listada, len(texto.encode()) - len(frente.group(1).encode())\n'
        '\n'
        '\n'
        '@functools.lru_cache(maxsize=1)\n'
        'def interpretador_com_nome_portatil() -> str:\n'
        '    for nome in CANDIDATOS_DE_INTERPRETADOR:\n'
        '        if not shutil.which(nome):\n'
        '            continue\n'
        '        try:\n'
        '            pronto = subprocess.run(\n'
        '                [nome, "-c", PERGUNTA_DA_VERSAO], capture_output=True,\n'
        '                text=True, timeout=TETO_DO_INTERPRETADOR_S)\n'
        '        except (OSError, subprocess.SubprocessError):\n'
        '            continue\n'
        '        if pronto.returncode == 0 and \\\n'
        '                pronto.stdout.strip() == VERSAO_QUE_SERVE:\n'
        '            return nome\n'
        '    return CANDIDATOS_DE_INTERPRETADOR[0]\n'
        '\n'
        '\n'
        'def comandos_dos_ganchos(raiz: Path, arquivos: tuple,\n'
        '                         evento: str) -> list:\n'
        '    comandos = []\n'
        '    for nome in arquivos:\n'
        '        try:\n'
        '            dado = json.loads(\n'
        '                (raiz / nome).read_text(encoding="utf-8"))\n'
        '        except (OSError, ValueError):\n'
        '            continue\n'
        '        eventos = dado.get(CHAVE_DOS_GANCHOS) or {}\n'
        '        escolhidos = ([eventos.get(evento) or []] if evento\n'
        '                      else list(eventos.values()))\n'
        '        for blocos in escolhidos:\n'
        '            for bloco in blocos:\n'
        '                for gancho in (bloco.get(CHAVE_DOS_GANCHOS) or []):\n'
        '                    if gancho.get(CHAVE_DO_COMANDO):\n'
        '                        comandos.append(gancho[CHAVE_DO_COMANDO])\n'
        '    return comandos\n'
        '\n'
        '\n'
        'def interpretadores_que_somem(comandos: list) -> list:\n'
        '    ausentes = []\n'
        '    for comando in comandos:\n'
        '        pedacos = shlex.split(comando)\n'
        '        if not pedacos:\n'
        '            continue\n'
        '        chamado = pedacos[0]\n'
        '        if shutil.which(chamado) or Path(chamado).is_file():\n'
        '            continue\n'
        '        if chamado not in ausentes:\n'
        '            ausentes.append(chamado)\n'
        '    return sorted(ausentes)\n'
        '\n'
        '\n'
        'def ganchos_com_interpretador_que_some(raiz: Path) -> list:\n'
        '    return interpretadores_que_somem(\n'
        '        comandos_dos_ganchos(raiz, CONFIGURACOES_DO_CLAUDE, ""))\n'
        '\n'
        '\n'
        'def comandos_de_abertura(raiz: Path) -> list:\n'
        '    return comandos_dos_ganchos(raiz, CONFIGURACOES_DO_CLAUDE,\n'
        '                                EVENTO_DE_ABERTURA)\n'
        '\n'
        '\n'
        'def bytes_que_os_ganchos_injetam(raiz: Path) -> tuple:\n'
        '    total, cegos = 0, 0\n'
        '    for comando in comandos_de_abertura(raiz):\n'
        '        real = comando.replace(RAIZ_NO_COMANDO, str(raiz)).replace(\n'
        '            RAIZ_NO_COMANDO_SEM_CHAVES, str(raiz))\n'
        '        try:\n'
        '            pronto = subprocess.run(\n'
        '                real, shell=True, input=ENTRADA_VAZIA_DO_GANCHO,\n'
        '                capture_output=True, text=True, cwd=raiz,\n'
        '                timeout=TEMPO_DE_UM_GANCHO)\n'
        '        except (OSError, subprocess.SubprocessError):\n'
        '            cegos += 1\n'
        '            continue\n'
        '        if pronto.returncode != 0:\n'
        '            cegos += 1\n'
        '            continue\n'
        '        if not pronto.stdout.strip():\n'
        '            continue\n'
        '        try:\n'
        '            injetado = json.loads(pronto.stdout)[\n'
        '                CHAVE_DA_SAIDA_DO_GANCHO][CHAVE_DO_CONTEXTO_INJETADO]\n'
        '            total += len(injetado.encode())\n'
        '        except (ValueError, KeyError, TypeError, AttributeError):\n'
        '            cegos += 1\n'
        '    return total, cegos\n'
        '\n'
        '\n'
        'def lotes_de_caminhos(alvos: list) -> list:\n'
        '    lotes, atual, tamanho = [], [], 0\n'
        '    for caminho in alvos:\n'
        '        if atual and tamanho + len(caminho) > TETO_DE_ARGUMENTOS:\n'
        '            lotes.append(atual)\n'
        '            atual, tamanho = [], 0\n'
        '        atual.append(caminho)\n'
        '        tamanho += len(caminho) + 1\n'
        '    if atual:\n'
        '        lotes.append(atual)\n'
        '    return lotes\n'
        '\n'
        '\n'
        'def soma_das_contagens(saida: str):\n'
        '    total = 0\n'
        '    for linha in saida.split("\\n"):\n'
        '        if not linha:\n'
        '            continue\n'
        '        try:\n'
        '            total += int(linha.rsplit(":", 1)[1])\n'
        '        except (ValueError, IndexError):\n'
        '            return None\n'
        '    return total\n'
        '\n'
        '\n'
        'def quantas_linhas_casam(padrao: str, alvos: list, raiz: Path):\n'
        '    total = 0\n'
        '    for lote in lotes_de_caminhos(alvos):\n'
        '        try:\n'
        '            pronto = subprocess.run(\n'
        '                ["grep", "-cHInP", padrao] + lote, cwd=raiz,\n'
        '                capture_output=True, text=True,\n'
        '                timeout=TEMPO_DE_UM_TESTE)\n'
        '        except (OSError, subprocess.SubprocessError):\n'
        '            return None\n'
        '        if pronto.returncode >= GREP_ERROU_A_PARTIR_DE:\n'
        '            return None\n'
        '        do_lote = soma_das_contagens(pronto.stdout)\n'
        '        if do_lote is None:\n'
        '            return None\n'
        '        total += do_lote\n'
        '    return total\n'
        '\n'
        '\n'
        'def perdao_do_termo(termo: dict, alvos: list, raiz: Path) -> tuple:\n'
        '    perdoadas, sem_referente = 0, []\n'
        '    for excecao in termo.get("excecoes", []):\n'
        '        quantas = excecao.get("ocorrencias") or 0\n'
        '        if not quantas:\n'
        '            continue\n'
        '        declarados = excecao.get("arquivos") or []\n'
        '        if not declarados:\n'
        '            sem_referente.append(excecao.get("caso") or EXCECAO_SEM_CASO)\n'
        '            continue\n'
        '        referentes = [a for a in declarados if a in alvos]\n'
        '        if not referentes:\n'
        '            continue\n'
        '        no_referente = quantas_linhas_casam(\n'
        '            termo["pronto"]["padrao"], referentes, raiz)\n'
        '        if no_referente is None:\n'
        '            return None, sem_referente\n'
        '        perdoadas += min(quantas, no_referente)\n'
        '    return perdoadas, sem_referente\n'
        '\n'
        '\n'
        'def saldo_do_vocabulario(raiz: Path) -> list:\n'
        '    fonte = raiz / FONTE_DO_VOCABULARIO\n'
        '    if not fonte.is_file():\n'
        '        return []\n'
        '    try:\n'
        '        termos = json.loads(fonte.read_text(encoding="utf-8"))["termos"]\n'
        '    except (json.JSONDecodeError, KeyError, TypeError):\n'
        '        return []\n'
        '    listados = corre(f\'cd "{raiz}" && git ls-files\')[1].split("\\n")\n'
        '    alvos = [c for c in listados\n'
        '             if c and c not in FORA_DA_CONTA_DO_VOCABULARIO]\n'
        '    if not alvos:\n'
        '        return []\n'
        '    contas = []\n'
        '    for termo in termos:\n'
        '        achadas = quantas_linhas_casam(\n'
        '            termo["pronto"]["padrao"], alvos, raiz)\n'
        '        perdoadas, sem_referente = perdao_do_termo(termo, alvos, raiz)\n'
        '        cego = achadas is None or perdoadas is None\n'
        '        saldo = None if cego else max(achadas - perdoadas, 0)\n'
        '        contas.append((termo["id"], achadas, perdoadas or 0, saldo,\n'
        '                       sem_referente))\n'
        '    return contas\n'
        '\n'
        '\n'
        'def folga_do_termo(bruto, perdoadas: int) -> int:\n'
        '    return 0 if bruto is None else max(perdoadas - bruto, 0)\n'
        '\n'
        '\n'
        'def vocabulario(raiz: Path) -> int:\n'
        '    contas = saldo_do_vocabulario(raiz)\n'
        '    if not contas:\n'
        '        print(SEM_VOCABULARIO.format(FONTE_DO_VOCABULARIO))\n'
        '        return 0\n'
        '    print(f"\\n{TITULO_VOCABULARIO}")\n'
        '    orfas = []\n'
        '    for nome, bruto, perdoadas, saldo, sem_referente in contas:\n'
        '        folga = folga_do_termo(bruto, perdoadas)\n'
        '        print(LINHA_DO_TERMO.format(\n'
        '            nome, SEM_MEDIDA if bruto is None else bruto, perdoadas,\n'
        '            SEM_MEDIDA if saldo is None else saldo,\n'
        '            TERMO_NAO_MEDIDO if saldo is None else\n'
        '            (TERMO_ABERTO if saldo else\n'
        '             (TERMO_COM_FOLGA.format(folga) if folga else TERMO_FECHADO))))\n'
        '        orfas += [(nome, caso) for caso in sem_referente]\n'
        '    for nome, caso in orfas:\n'
        '        print(EXCECAO_SEM_REFERENTE.format(termo=nome, caso=caso))\n'
        '    cegos = sum(1 for _, _, _, saldo, _ in contas if saldo is None)\n'
        '    aberto = sum(saldo for _, _, _, saldo, _ in contas if saldo is not None)\n'
        '    folgas = sum(folga_do_termo(bruto, perdoadas)\n'
        '                 for _, bruto, perdoadas, _, _ in contas)\n'
        '    if cegos:\n'
        '        print(VOCABULARIO_NAO_MEDIDO.format(cegos))\n'
        '    elif aberto:\n'
        '        print(VOCABULARIO_ABERTO.format(aberto))\n'
        '    elif folgas:\n'
        '        print(VOCABULARIO_COM_FOLGA.format(folgas))\n'
        '    else:\n'
        '        print(VOCABULARIO_FECHADO)\n'
        '    return 1 if (aberto or cegos or folgas) else 0\n'
        '\n'
        '\n'
        'def branches_de_longa_duracao(raiz: Path) -> set:\n'
        '    try:\n'
        '        linhas = (raiz / ARQUIVO_DAS_PROTEGIDAS).read_text(\n'
        '            encoding="utf-8").splitlines()\n'
        '    except OSError:\n'
        '        return set()\n'
        '    return {l.strip().lower() for l in linhas if l.strip()\n'
        '            and not l.strip().startswith(MARCA_DE_COMENTARIO_NA_LISTA)}\n'
        '\n'
        '\n'
        'def branch_de_incorporacao(raiz: Path) -> str:\n'
        '    try:\n'
        '        dado = json.loads((raiz / ARQUIVO_DE_CONFIGURACAO).read_text(\n'
        '            encoding="utf-8"))\n'
        '    except (OSError, ValueError):\n'
        '        return ""\n'
        '    declaradas = dado.get(CHAVE_POR_INCORPORACAO) if isinstance(dado, dict) \\\n'
        '        else None\n'
        '    if not isinstance(declaradas, list):\n'
        '        return ""\n'
        '    nomes = [n for n in declaradas if isinstance(n, str) and n.strip()]\n'
        '    return nomes[0].strip() if nomes else ""\n'
        '\n'
        '\n'
        'def referencia_que_existe(raiz: Path, nome: str) -> str:\n'
        '    for candidata in (f"{PREFIXO_DO_REMOTO}{nome}", nome):\n'
        '        codigo, _ = corre(\n'
        '            f\'cd "{raiz}" && {COMANDO_DA_REFERENCIA.format(candidata)}\')\n'
        '        if codigo == 0:\n'
        '            return candidata\n'
        '    return ""\n'
        '\n'
        '\n'
        'def nome_curto_da_branch(bruta: str) -> str:\n'
        '    sem_remoto = bruta.split(PREFIXO_DO_REMOTO, 1)[-1] \\\n'
        '        if bruta.startswith(PREFIXO_DO_REMOTO) else bruta\n'
        '    return sem_remoto.strip()\n'
        '\n'
        '\n'
        'def branches_ja_entregues(raiz: Path, referencia: str, atual: str,\n'
        '                          protegidas: set) -> tuple:\n'
        '    def topo(nome):\n'
        '        codigo, saida = corre(f\'cd "{raiz}" && {COMANDO_DO_TOPO.format(nome)}\')\n'
        '        return saida.strip() if codigo == 0 else ""\n'
        '\n'
        '    topo_da_referencia = topo(referencia)\n'
        '\n'
        '    def e_rastro(bruta):\n'
        '        if topo(bruta) == topo_da_referencia:\n'
        '            return False, True\n'
        '        codigo, _ = corre(\n'
        '            f\'cd "{raiz}" && \'\n'
        "            f'{COMANDO_DO_QUE_ACRESCENTA.format(referencia, bruta)}')\n"
        '        if codigo not in (NAO_ACRESCENTA_NADA, ACRESCENTA_ALGUMA_COISA):\n'
        '            return False, False\n'
        '        return codigo == NAO_ACRESCENTA_NADA, True\n'
        '\n'
        '    def colher(comando, e_remota):\n'
        '        codigo, saida = corre(f\'cd "{raiz}" && {comando}\')\n'
        '        if codigo != 0 or not topo_da_referencia:\n'
        '            return [], False\n'
        '        colhidas, mediu = [], True\n'
        '        for bruta in saida.split("\\n"):\n'
        '            bruta = bruta.strip().lstrip("* ").strip()\n'
        '            if not bruta or bruta.startswith(CABECA_DO_REMOTO):\n'
        '                continue\n'
        '            if e_remota and SEPARADOR_DO_REMOTO not in bruta:\n'
        '                continue\n'
        '            curto = nome_curto_da_branch(bruta)\n'
        '            if not curto or curto == atual or curto.lower() in protegidas:\n'
        '                continue\n'
        '            rastro, julgou = e_rastro(bruta)\n'
        '            mediu = mediu and julgou\n'
        '            if rastro:\n'
        '                colhidas.append(bruta)\n'
        '        return colhidas, mediu\n'
        '    locais, mediu_locais = colher(COMANDO_DAS_LOCAIS, False)\n'
        '    remotas, mediu_remotas = colher(COMANDO_DAS_REMOTAS, True)\n'
        '    return locais, remotas, mediu_locais and mediu_remotas\n'
        '\n'
        '\n'
        'def o_que_ainda_nao_saiu(raiz: Path, atual: str) -> int:\n'
        '    codigo, alvo = corre(f\'cd "{raiz}" && {COMANDO_DO_UPSTREAM}\')\n'
        '    if codigo != 0 or not alvo:\n'
        '        codigo, alvo = corre(\n'
        '            f\'cd "{raiz}" && {COMANDO_DO_ESPELHO.format(atual)}\')\n'
        '    if codigo != 0 or not alvo:\n'
        '        print(SEM_ENTREGA.format(atual, atual))\n'
        '        return 1\n'
        '    _, sobra = corre(\n'
        '        f\'cd "{raiz}" && {COMANDO_DO_QUE_FALTA.format(alvo)}\')\n'
        '    linhas = [l for l in sobra.split("\\n") if l.strip()]\n'
        '    if not linhas:\n'
        '        print(ENTREGA_LIMPA.format(atual, alvo))\n'
        '        return 0\n'
        '    print(ENTREGA_COM_SOBRA.format(len(linhas), atual, alvo))\n'
        '    for linha in linhas:\n'
        '        print(f"  {linha}")\n'
        '    return 1\n'
        '\n'
        '\n'
        'def o_que_saiu_e_ficou(raiz: Path, atual: str) -> int:\n'
        '    incorporacao = branch_de_incorporacao(raiz)\n'
        '    if not incorporacao:\n'
        '        print(PODA_SEM_INCORPORACAO.format(ARQUIVO_DE_CONFIGURACAO,\n'
        '                                           CHAVE_POR_INCORPORACAO))\n'
        '        return 0\n'
        '    referencia = referencia_que_existe(raiz, incorporacao)\n'
        '    if not referencia:\n'
        '        print(PODA_SEM_INCORPORACAO.format(ARQUIVO_DE_CONFIGURACAO,\n'
        '                                           CHAVE_POR_INCORPORACAO))\n'
        '        return 0\n'
        '    locais, remotas, mediu = branches_ja_entregues(\n'
        '        raiz, referencia, atual, branches_de_longa_duracao(raiz))\n'
        '    if not mediu:\n'
        '        print(PODA_NAO_MEDIDA)\n'
        '        return 1\n'
        '    if not locais and not remotas:\n'
        '        print(PODA_LIMPA)\n'
        '        return 0\n'
        '    print(PODA_COM_SOBRA.format(len(locais) + len(remotas), referencia))\n'
        '    if locais:\n'
        '        print(PODA_LOCAL.format(" ".join(locais)))\n'
        '    if remotas:\n'
        '        print(PODA_REMOTA.format(\n'
        '            " ".join(nome_curto_da_branch(r) for r in remotas)))\n'
        '    print(PODA_ESCAPE.format(ARQUIVO_DAS_PROTEGIDAS))\n'
        '    return 1\n'
        '\n'
        '\n'
        'def entrega(raiz: Path) -> int:\n'
        '    codigo, atual = corre(f\'cd "{raiz}" && {COMANDO_DA_BRANCH}\')\n'
        '    if codigo != 0 or not atual:\n'
        '        print(FORA_DE_REPOSITORIO)\n'
        '        return 0\n'
        '    print(f"\\n{TITULO_ENTREGA}")\n'
        '    faltou = o_que_ainda_nao_saiu(raiz, atual)\n'
        '    sobrou = o_que_saiu_e_ficou(raiz, atual)\n'
        '    return 1 if (faltou or sobrou) else 0\n'
        '\n'
        '\n'
        'def dias_parado(arquivo: Path, agora: float) -> int:\n'
        '    return int((agora - arquivo.stat().st_mtime) // SEGUNDOS_DO_DIA)\n'
        '\n'
        '\n'
        'def arquivos_do_rascunho(raiz: Path) -> list:\n'
        '    pasta = raiz / RASCUNHO\n'
        '    return sorted(a for a in pasta.rglob("*")\n'
        '                  if a.is_file() and a.relative_to(pasta).parts[0]\n'
        '                  not in PASTAS_DE_INSTRUMENTO_NO_RASCUNHO)\n'
        '\n'
        '\n'
        'def esquecidos_no_rascunho(arquivos: list, rastreados: set, raiz: Path,\n'
        '                           agora: float) -> list:\n'
        '    return [(rel, dias) for arquivo in arquivos\n'
        '            if (rel := arquivo.relative_to(raiz).as_posix()) not in rastreados\n'
        '            and (dias := dias_parado(arquivo, agora))\n'
        '            > TETO_DE_DIAS_NO_RASCUNHO]\n'
        '\n'
        '\n'
        'def rascunho(raiz: Path) -> int:\n'
        '    if not (raiz / RASCUNHO).is_dir():\n'
        '        print(SEM_RASCUNHO.format(RASCUNHO))\n'
        '        return 0\n'
        '    print(f"\\n{TITULO_RASCUNHO}")\n'
        '    for nome, motivo in sorted(PASTAS_DE_INSTRUMENTO_NO_RASCUNHO.items()):\n'
        '        print(LINHA_DA_PASTA_DE_INSTRUMENTO.format(f"{RASCUNHO}/{nome}",\n'
        '                                                   motivo))\n'
        '    rastreados = rastreados_por_git(raiz, COMANDO_DOS_RASCUNHOS_RASTREADOS)\n'
        '    if rastreados is None:\n'
        '        print(RASCUNHO_NAO_MEDIDO.format(COMANDO_DOS_RASCUNHOS_RASTREADOS))\n'
        '        return 1\n'
        '    arquivos = arquivos_do_rascunho(raiz)\n'
        '    esquecidos = esquecidos_no_rascunho(arquivos, set(rastreados), raiz,\n'
        '                                        time.time())\n'
        '    for rel, dias in esquecidos:\n'
        '        print(LINHA_DO_ESQUECIDO.format(rel, dias))\n'
        '    if esquecidos:\n'
        '        print(RASCUNHO_ENVELHECIDO.format(len(esquecidos), RASCUNHO,\n'
        '                                          TETO_DE_DIAS_NO_RASCUNHO))\n'
        '        return 1\n'
        '    print(RASCUNHO_EM_DIA.format(RASCUNHO, TETO_DE_DIAS_NO_RASCUNHO,\n'
        '                                 len(arquivos), len(rastreados)))\n'
        '    return 0\n'
        '\n'
        '\n'
        'PASTA_DAS_EVIDENCIAS = "execucoes/evidencias"\n'
        'CAMPO_DO_CUSTO = re.compile(r\'"total_cost_usd":([0-9.]+)\')\n'
        'TITULO_DA_CONTA = "A CONTA — o que cada execução custou, do que já está gravado"\n'
        'SEM_EVIDENCIAS = ("sem evidência gravada em {} — a conta não tem o que ler, "\n'
        '                  "e isso não é achado")\n'
        'LINHA_DA_EXECUCAO = "  {:<22} US$ {:>7.2f}   atribuído US$ {:>7.2f}"\n'
        'CONTA_DA_RODADA = ("Somam US$ {:.2f} cobrados em {} execução(ões). Não há "\n'
        '                   "teto declarado: esta rotina MEDE e não reprova, por "\n'
        '                   "decisão do dono em 30/08 — número sem procedência não "\n'
        '                   "vira cobrança, e a procedência se junta rodando.")\n'
        'TITULO_POR_ETAPA = "POR ETAPA — onde o dinheiro foi parar, somando os ciclos"\n'
        'LINHA_DA_ETAPA = ("  {:<22} US$ {:>7.2f}   {:>3} execução(ões)   {:>10}")\n'
        'DURACAO_EM_MINUTOS = "{:.1f} min"\n'
        'DURACAO_NAO_MEDIDA = "sem relógio"\n'
        'SEM_ETAPA_MEDIDA = ("nenhuma evidência traz custo: a régua por etapa só vale "\n'
        '                    "para execução gravada depois de 01/09 — o que veio "\n'
        '                    "antes some aqui de propósito, e não vira zero")\n'
        'FORA_DA_REGUA = (\n'
        '    "US$ {:.2f} em {} execução(ões) ficam fora desta tabela: a evidência "\n'
        '    "delas não atribuiu NADA a etapa nenhuma. Ou são anteriores à régua da "\n'
        '    "etapa, ou toda sessão delas morreu sem registrar o que gastou — daqui "\n'
        '    "não dá para separar as duas, e chamar tudo de história seria inventar. "\n'
        '    "O log é a única fonte que resta para elas.")\n'
        'BURACO_DA_ATRIBUICAO = (\n'
        '    "Dentro da régua, US$ {:.2f} de US$ {:.2f} cobrados não caíram em etapa "\n'
        '    "nenhuma ({:.0f}%). Esse buraco é sessão que morreu sem deixar "\n'
        '    "evidência: o "\n'
        '    "log cobra, a evidência não registra. Ele é a medida do retrabalho "\n'
        '    "invisível, não erro de soma.")\n'
        'ATRIBUICAO_FECHADA = ("Dentro da régua, tudo que o log cobrou caiu em etapa: "\n'
        '                      "a medição por etapa fecha com a cobrança.")\n'
        'SOBRA_NA_ATRIBUICAO = (\n'
        '    "As etapas somam US$ {:.2f} A MAIS do que os US$ {:.2f} que o log cobrou. "\n'
        '    "As duas fontes discordam, e para cima: log truncado ou rodado, ou "\n'
        '    "evidência sem a linha correspondente no log. Não é conta fechada — é "\n'
        '    "discordância, e ela se diz nos dois sentidos.")\n'
        '\n'
        '\n'
        'def _evidencias(pasta: Path):\n'
        '    for arquivo in sorted(pasta.glob("*/*.json")):\n'
        '        try:\n'
        '            dado = json.loads(arquivo.read_text(encoding="utf-8"))\n'
        '        except (OSError, ValueError):\n'
        '            continue\n'
        '        if isinstance(dado, dict) and isinstance(dado.get("etapa"), str):\n'
        '            yield arquivo.parent.name, dado\n'
        '\n'
        '\n'
        'def _usd_da_evidencia(dado: dict):\n'
        '    custo = dado.get("custo")\n'
        '    usd = custo.get("usd") if isinstance(custo, dict) else None\n'
        '    return usd if isinstance(usd, (int, float)) \\\n'
        '        and not isinstance(usd, bool) else None\n'
        '\n'
        '\n'
        'def custo_por_etapa(raiz: Path) -> list:\n'
        '    pasta = raiz / PASTA_DAS_EVIDENCIAS\n'
        '    if not pasta.is_dir():\n'
        '        return []\n'
        '    contas = {}\n'
        '    for _, dado in _evidencias(pasta):\n'
        '        usd = _usd_da_evidencia(dado)\n'
        '        if usd is None:\n'
        '            continue\n'
        '        dolar, quantas, segundos = contas.get(dado["etapa"], (0.0, 0, 0.0))\n'
        '        duracao = dado.get("duracao")\n'
        '        contas[dado["etapa"]] = (\n'
        '            dolar + usd, quantas + 1,\n'
        '            segundos + (duracao if isinstance(duracao, (int, float))\n'
        '                        and not isinstance(duracao, bool) else 0.0))\n'
        '    return sorted(((n, d, q, s) for n, (d, q, s) in contas.items()),\n'
        '                  key=lambda linha: -linha[1])\n'
        '\n'
        '\n'
        'def custo_das_execucoes(raiz: Path) -> list:\n'
        '    pasta = raiz / PASTA_DAS_EVIDENCIAS\n'
        '    if not pasta.is_dir():\n'
        '        return []\n'
        '    cobrado = {}\n'
        '    for log in sorted(pasta.glob("*/*.log")):\n'
        '        try:\n'
        '            texto = log.read_text(encoding="utf-8", errors="replace")\n'
        '        except OSError:\n'
        '            continue\n'
        '        cobrado[log.parent.name] = cobrado.get(log.parent.name, 0.0) + sum(\n'
        '            float(achado.group(1)) for achado in CAMPO_DO_CUSTO.finditer(texto))\n'
        '    atribuido = {}\n'
        '    for trabalho, dado in _evidencias(pasta):\n'
        '        usd = _usd_da_evidencia(dado)\n'
        '        if usd is not None:\n'
        '            atribuido[trabalho] = atribuido.get(trabalho, 0.0) + usd\n'
        '    return sorted(((nome, dolar, atribuido.get(nome, 0.0))\n'
        '                   for nome, dolar in cobrado.items() if dolar),\n'
        '                  key=lambda linha: -linha[1])\n'
        '\n'
        '\n'
        'def conta(raiz: Path) -> int:\n'
        '    print(f"\\n{TITULO_DA_CONTA}")\n'
        '    linhas = custo_das_execucoes(raiz)\n'
        '    if not linhas:\n'
        '        print(SEM_EVIDENCIAS.format(PASTA_DAS_EVIDENCIAS))\n'
        '        return 0\n'
        '    for nome, dolar, posto in linhas:\n'
        '        print(LINHA_DA_EXECUCAO.format(nome, dolar, posto))\n'
        '    total = sum(l[1] for l in linhas)\n'
        '    print(CONTA_DA_RODADA.format(total, len(linhas)))\n'
        '\n'
        '    print(f"\\n{TITULO_POR_ETAPA}")\n'
        '    etapas = custo_por_etapa(raiz)\n'
        '    if not etapas:\n'
        '        print(SEM_ETAPA_MEDIDA)\n'
        '        return 0\n'
        '    for nome, dolar, quantas, segundos in etapas:\n'
        '        print(LINHA_DA_ETAPA.format(\n'
        '            nome, dolar, quantas,\n'
        '            DURACAO_EM_MINUTOS.format(segundos / 60) if segundos\n'
        '            else DURACAO_NAO_MEDIDA))\n'
        '    na_regua = [linha for linha in linhas if linha[2]]\n'
        '    cru = [linha for linha in linhas if not linha[2]]\n'
        '    if cru:\n'
        '        print(FORA_DA_REGUA.format(sum(l[1] for l in cru), len(cru)))\n'
        '    cobrado = sum(l[1] for l in na_regua)\n'
        '    buraco = cobrado - sum(l[2] for l in na_regua)\n'
        '    if round(buraco, 2) > 0:\n'
        '        print(BURACO_DA_ATRIBUICAO.format(buraco, cobrado,\n'
        '                                          100 * buraco / cobrado))\n'
        '    elif round(buraco, 2) < 0:\n'
        '        print(SOBRA_NA_ATRIBUICAO.format(-buraco, cobrado))\n'
        '    else:\n'
        '        print(ATRIBUICAO_FECHADA)\n'
        '    return 0\n'
        '\n'
        '\n'
        'def teto_da_largada(raiz: Path):\n'
        '    try:\n'
        '        dado = json.loads(\n'
        '            (raiz / ARQUIVO_DE_CONFIGURACAO).read_text(encoding="utf-8"))\n'
        '    except (OSError, ValueError):\n'
        '        return None\n'
        '    declarado = dado.get(CHAVE_DO_TETO) if isinstance(dado, dict) else None\n'
        '    return declarado if isinstance(declarado, int) else None\n'
        '\n'
        '\n'
        'def largada(raiz: Path) -> int:\n'
        '    print(f"\\n{TITULO_LARGADA}")\n'
        '    paga = medir(raiz)[1]["largada"]\n'
        '    teto = teto_da_largada(raiz)\n'
        '    if teto is None:\n'
        '        print(LARGADA_SEM_TETO.format(paga, ARQUIVO_DE_CONFIGURACAO,\n'
        '                                      CHAVE_DO_TETO))\n'
        '        return 0\n'
        '    if paga > teto:\n'
        '        print(LARGADA_ACIMA.format(paga, teto))\n'
        '        return 1\n'
        '    print(LARGADA_NA_REGUA.format(paga, teto))\n'
        '    return 0\n'
        '\n'
        '\n'
        'def rastreados_por_git(raiz: Path, comando: str):\n'
        '    codigo, saida = corre(f\'cd "{raiz}" && {comando}\')\n'
        '    if codigo != 0:\n'
        '        return None\n'
        '    return sorted(l.strip() for l in saida.split("\\n") if l.strip())\n'
        '\n'
        '\n'
        'def escopo_do_instalador(raiz: Path) -> tuple:\n'
        '    escopo = {"__name__": NOME_DO_ESCOPO_DA_MATRICULA}\n'
        '    try:\n'
        '        fonte = (raiz / INSTALADOR).read_text(encoding="utf-8")\n'
        '        exec(compile(fonte, INSTALADOR, "exec"), escopo)\n'
        '    except Exception as erro:\n'
        '        return None, f"{type(erro).__name__}: {erro}"\n'
        '    return escopo, ""\n'
        '\n'
        '\n'
        'def matricula_do_instalador(raiz: Path) -> tuple:\n'
        '    escopo, erro = escopo_do_instalador(raiz)\n'
        '    if escopo is None:\n'
        '        return None, erro\n'
        '    declarados = set()\n'
        '    for valor in escopo.values():\n'
        '        if type(valor).__name__ == NOME_DO_GANCHO_DECLARADO:\n'
        '            declarados.update(CAMINHO_DE_GANCHO.findall(valor.comando))\n'
        '    por_modulo = set()\n'
        '    for arquivos in (escopo.get(NOME_DE_MODULOS) or {}).values():\n'
        '        por_modulo.update(arquivos)\n'
        '    return (tuple(escopo.get(NOME_DE_FONTES) or ()), declarados,\n'
        '            por_modulo), ""\n'
        '\n'
        '\n'
        'def embutidos_sob(raiz: Path, fontes: tuple, prefixo: str) -> set:\n'
