        '    literais = {p for p in fontes if p.startswith(prefixo)\n'
        '                and not set(p) & set(CARACTERES_DE_GLOB)}\n'
        '    return sorted(c for c in literais | declarados\n'
        '                  if not (raiz / c).is_file())\n'
        '\n'
        '\n'
        'def ganchos_ligados_fora_do_git(raiz: Path, ganchos: list) -> list:\n'
        '    ligados = set()\n'
        '    for comando in comandos_dos_ganchos(raiz, CONFIGURACOES_DO_CLAUDE,\n'
