        '        ligados.update(CAMINHO_DE_GANCHO.findall(comando))\n'
        '    return sorted(c for c in ligados\n'
        '                  if c not in set(ganchos) and (raiz / c).is_file())\n'
        '\n'
        '\n'
        'def saldos_da_matricula(raiz: Path, ganchos: list, fontes: tuple,\n'
        '                        declarados: set) -> list:\n'
        '    embutidos = embutidos_sob(raiz, fontes, f"{PASTA_DOS_GANCHOS}/")\n'
        '    ligados = set()\n'
        '    for comando in comandos_dos_ganchos(raiz, (ARQUIVO_SETTINGS,),\n'
        '                                        TODOS_OS_EVENTOS):\n'
        '        ligados.update(CAMINHO_DE_GANCHO.findall(comando))\n'
        '    saldos = [(c, SALDO_NAO_VIAJA) for c in ganchos\n'
        '              if c not in embutidos]\n'
        '    saldos += [(c, SALDO_ORFA)\n'
        '               for c in matriculas_orfas(raiz, fontes, declarados)]\n'
        '    saldos += [(c, SALDO_SEM_DECLARACAO)\n'
        '               for c in sorted(ligados - declarados)]\n'
        '    saldos += [(c, SALDO_DESLIGADO)\n'
        '               for c in sorted(declarados - ligados)\n'
