        '                     f"{dados[\'injetado_por_gancho\']} bytes"\n'
        '                     + (f" ({dados[\'ganchos_nao_medidos\']} gancho(s) não medido(s))"\n'
        '                        if dados["ganchos_nao_medidos"] else "")),\n'
        '        LINHA.format("corpo de skill — só ao disparar",\n'
        '                     f"{dados[\'adiado\']} bytes"),\n'
        '        LINHA.format(f"  acima do teto de {TETO_DO_CORPO_DA_SKILL} bytes",\n'
        '                     ", ".join(SKILL_ACIMA_DO_TETO.format(nome, peso)\n'
        '                               for nome, peso in acima_do_teto)\n'
        '                     or NENHUMA_SKILL_ACIMA),\n'
        '        LINHA.format("  fora do alcance deste repositório",\n'
        '                     _recado_da_listagem(dados)),\n'
        '        LINHA.format(f"páginas em {PASTA_DO_CONHECIMENTO}/",\n'
        '                     f"{dados[\'paginas\']} ({dados[\'bytes_das_paginas\']} bytes)"),\n'
        '        LINHA.format("ganchos no disco", dados["ganchos"]),\n'
        '        LINHA.format("subagentes no disco",\n'
        '                     f"{dados[\'subagentes\']}"\n'
        '                     f" ({dados[\'subagentes_sem_coleira\']} sem coleira)"),\n'
        '    ]\n'
        '    return linhas, dados\n'
        '\n'
        '\n'
        'def resumo_da_suite(saida: str) -> str:\n'
        '    linhas = [l for l in saida.splitlines() if l.strip()]\n'
        '    resumo = next((l for l in reversed(linhas)\n'
        '                   if l.startswith(MARCAS_DE_RESUMO)), linhas[-1] if linhas else "")\n'
        '    return resumo[:52]\n'
        '\n'
        '\n'
        'def instrumentos_com_teste(raiz: Path) -> list:\n'
        '    alvos = sorted(raiz.glob(GLOB_PYTHON))\n'
        '    alvos += sorted((raiz / PASTA_DOS_GANCHOS).glob(GLOB_PYTHON))\n'
        '    alvos += sorted((raiz / PASTA_DOS_INSTRUMENTOS).rglob(GLOB_PYTHON))\n'
        '    return [a for a in alvos\n'
        '            if BANDEIRA_DE_TESTE in a.read_text(encoding="utf-8", errors="replace")]\n'
        '\n'
        '\n'
        'def casos_da_suite(saida: str) -> int:\n'
        '    limpo = saida.strip()\n'
        '    if PALAVRA_DE_CASO not in limpo.lower():\n'
        '        return 0\n'
        '    numeros = [int(p) for p in limpo.replace(":", " ").split() if p.isdigit()]\n'
        '    return numeros[0] if numeros else 0\n'
        '\n'
        '\n'
        'def provar(raiz: Path) -> tuple:\n'
        '    linhas, caidos, rodados = [], [], 0\n'
        '    segundos, casos = 0.0, 0\n'
        '    for alvo in instrumentos_com_teste(raiz):\n'
        '        partida = time.monotonic()\n'
        '        codigo, saida = corre(\n'
        '            f\'cd "{raiz}" && {INTERPRETADOR_NO_SHELL} "{alvo.relative_to(raiz)}" {BANDEIRA_DE_TESTE}\')\n'
        '        gasto = time.monotonic() - partida\n'
        '        segundos += gasto\n'
        '        provados = casos_da_suite(resumo_da_suite(saida))\n'
        '        casos += provados\n'
        '        rodados += 1\n'
        '        proprio_nada = codigo == 0 and provados == 0\n'
        '        if codigo != 0 or proprio_nada:\n'
        '            caidos.append(alvo.name)\n'
        '        linhas.append(LINHA_DE_CASO.format(\n'
        '            "NADA" if proprio_nada else ("OK  " if codigo == 0 else "CAIU"),\n'
        '            f"{alvo.relative_to(raiz)} — {gasto:.1f}s — "\n'
        '            f"{resumo_da_suite(saida)}"))\n'
        '    sem_teste = [p.name for p in sorted((raiz / PASTA_DOS_GANCHOS).glob(GLOB_PYTHON))\n'
        '                 if BANDEIRA_DE_TESTE not in p.read_text(encoding="utf-8",\n'
        '                                                         errors="replace")]\n'
        '    for nome in sem_teste:\n'
        '        linhas.append(LINHA_DE_CASO.format("CAIU", f"{nome} — sem --testar próprio"))\n'
        '    if (raiz / INSTALADOR).is_file():\n'
        '        codigo, _ = corre(f\'cd "{raiz}" && {INTERPRETADOR_NO_SHELL} {INSTALADOR} --verificar\')\n'
        '        rodados += 1\n'
        '        if codigo != 0:\n'
        '            caidos.append(INSTALADOR)\n'
        '        linhas.append(LINHA_DE_CASO.format(\n'
        '            "OK  " if codigo == 0 else "CAIU", f"{INSTALADOR} --verificar"))\n'
        '    return linhas, {"rodados": rodados, "caem": len(caidos) + len(sem_teste),\n'
        '                    "sem_teste": len(sem_teste),\n'
        '                    "segundos": round(segundos, 1), "casos": casos}\n'
        '\n'
        '\n'
        'def _texto(valor):\n'
        '    return str(valor).lower()\n'
        '\n'
        '\n'
        'def _comeca_com(valor, aceitos):\n'
        '    return _texto(valor).lstrip(\' "\\\'\').startswith(tuple(aceitos))\n'
        '\n'
        '\n'
        'def quantas_regras(raiz: Path):\n'
        '    fonte = raiz / FONTE_DAS_REGRAS\n'
        '    if not fonte.is_file():\n'
        '        return None\n'
        '    try:\n'
        '        return len(json.loads(fonte.read_text(encoding="utf-8"))["regras"])\n'
        '    except (json.JSONDecodeError, KeyError, TypeError):\n'
        '        return None\n'
        '\n'
        '\n'
        'def perguntas(quantas_regras):\n'
        '    return (\n'
        '        ("abre na raiz", "onde_abrir",\n'
        '         lambda r: "raiz" in _texto(r.get("onde_abrir"))),\n'
        '        ("conta as regras", "quantas_regras",\n'
        '         lambda r: r.get("quantas_regras") == quantas_regras),\n'
        '        ("não commita por conta", "posso_commitar",\n'
        '         lambda r: _comeca_com(r.get("posso_commitar"),\n'
        '                               ("nao", "não", "depende"))),\n'
        '        ("segredo vira variável", "segredo_em_texto_rastreado",\n'
        '         lambda r: "${" in str(r.get("segredo_em_texto_rastreado"))\n'
        '         or "variáve" in _texto(r.get("segredo_em_texto_rastreado"))\n'
        '         or "variave" in _texto(r.get("segredo_em_texto_rastreado"))),\n'
        '        ("não toca em branch de longa duração", "branch_de_longa_duracao",\n'
        '         lambda r: any(p in _texto(r.get("branch_de_longa_duracao"))\n'
        '                       for p in ("não", "nao", "nunca"))),\n'
        '        ("pronto é o que instrumento provou", "o_que_e_pronto",\n'
        '         lambda r: "instrumento" in _texto(r.get("o_que_e_pronto"))\n'
        '         or "prov" in _texto(r.get("o_que_e_pronto"))),\n'
        '    )\n'
        '\n'
        '\n'
        'def colher_json(texto: str) -> dict:\n'
        '    for corte in (texto, texto[texto.find("{"):texto.rfind("}") + 1]):\n'
        '        with contextlib.suppress(ValueError):\n'
        '            dado = json.loads(corte)\n'
        '            if isinstance(dado, dict):\n'
        '                return dado\n'
        '    return {}\n'
        '\n'
        '\n'
        'def regioes_de_teste(arvore: ast.AST) -> list:\n'
        '    achadas = []\n'
        '    for no in ast.walk(arvore):\n'
        '        if isinstance(no, FORMAS_DE_FUNCAO) \\\n'
        '                and MARCA_DE_TESTE_NO_NOME in no.name.lower():\n'
        '            achadas.append((no, no.name))\n'
        '        elif isinstance(no, ast.If) \\\n'
        '                and MARCA_DA_BANDEIRA_DE_TESTE in ast.dump(no.test).lower():\n'
        '            achadas.append((no, ""))\n'
        '    return achadas\n'
        '\n'
        '\n'
        'def teste_toca_o_proprio_codigo(caminho: Path) -> bool:\n'
        '    with contextlib.suppress(OSError, SyntaxError):\n'
        '        arvore = ast.parse(caminho.read_text(encoding="utf-8"))\n'
        '        do_arquivo = {no.name for no in ast.walk(arvore)\n'
        '                      if isinstance(no, FORMAS_DE_FUNCAO)}\n'
        '        for regiao, nome_da_regiao in regioes_de_teste(arvore):\n'
        '            chamados = {c.func.id for c in ast.walk(regiao)\n'
        '                        if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)}\n'
        '            if chamados & (do_arquivo - {nome_da_regiao}):\n'
        '                return True\n'
        '    return False\n'
        '\n'
        '\n'
        'def simular(raiz: Path) -> tuple:\n'
        '    if not shutil.which("claude"):\n'
        '        return [SEM_CLAUDE], {"rodou": False}\n'
        '    fonte = raiz / FONTE_DAS_REGRAS\n'
        '    if not fonte.is_file():\n'
        '        return [SEM_REGRAS], {"rodou": False}\n'
        '\n'
        '    quantas = len(json.loads(fonte.read_text(encoding="utf-8"))["regras"])\n'
        '    alvo = raiz / ARQUIVO_PEDIDO\n'
        '    alvo.parent.mkdir(parents=True, exist_ok=True)\n'
        '    with contextlib.suppress(OSError):\n'
        '        alvo.unlink()\n'
        '\n'
        '    partida = time.monotonic()\n'
        '    _, bruto = corre(\n'
        '        f\'cd "{raiz}" && claude -p {json.dumps(PEDIDO.format(arquivo=ARQUIVO_PEDIDO))} \'\n'
        "        f'--output-format json --model {MODELO_DA_SIMULACAO} '\n"
        '        f\'--allowedTools "{FERRAMENTAS_DA_SIMULACAO}"\',\n'
        '        tempo=TEMPO_DA_SIMULACAO)\n'
        '    parede = time.monotonic() - partida\n'
        '\n'
        '    sessao = colher_json(bruto)\n'
        '    resposta = colher_json(str(sessao.get("result", "")))\n'
        '    do_nucleo = [(rotulo, bool(prova(resposta)),\n'
        '                  "" if prova(resposta) else str(resposta.get(chave, ""))[:44])\n'
        '                 for rotulo, chave, prova in perguntas(quantas)]\n'
        '    do_artefato = []\n'
        '\n'
        '    if alvo.is_file():\n'
        '        codigo_do_teste, berro = corre(\n'
        '            f\'cd "{raiz}" && {INTERPRETADOR_NO_SHELL} "{ARQUIVO_PEDIDO}" {BANDEIRA_DE_TESTE}\')\n'
        '    else:\n'
        '        codigo_do_teste, berro = 1, "a sessão não escreveu o arquivo"\n'
        '    do_artefato.append((f"entregou {ARQUIVO_PEDIDO} com --testar que passa",\n'
        '                        alvo.is_file() and codigo_do_teste == 0,\n'
        '                        berro.strip().splitlines()[-1][:44] if berro else ""))\n'
        '    do_artefato.append(("o --testar exercita o código do arquivo",\n'
        '                        alvo.is_file() and teste_toca_o_proprio_codigo(alvo),\n'
        '                        ""))\n'
        '    acertos = do_nucleo + do_artefato\n'
        '    with contextlib.suppress(OSError):\n'
        '        alvo.unlink()\n'
        '\n'
        '    certos = sum(1 for _, ok, _ in acertos if ok)\n'
        '    uso = sessao.get("usage") or {}\n'
        '    linhas = [LINHA_DE_CASO.format("OK  " if ok else "CAIU",\n'
        '                                   f"{rotulo}{\'  \' + porque if porque else \'\'}")\n'
        '              for rotulo, ok, porque in acertos]\n'
        '    linhas += [\n'
        '        LINHA.format("acurácia", f"{certos}/{len(acertos)}"),\n'
        '        LINHA.format("turnos", sessao.get("num_turns", "?")),\n'
        '        LINHA.format("tempo de parede", f"{parede:.1f} s"),\n'
        '        LINHA.format("dólar", f"{sessao.get(\'total_cost_usd\', 0):.4f}"),\n'
        '        LINHA.format("tokens de saída", uso.get("output_tokens", "?")),\n'
        '    ]\n'
        '    return linhas, {"rodou": True, "acertos": certos, "casos": len(acertos),\n'
        '                    "certas_do_nucleo": sum(1 for _, ok, _ in do_nucleo if ok),\n'
        '                    "casos_do_nucleo": len(do_nucleo),\n'
        '                    "caidas_do_nucleo": [rotulo for rotulo, ok, _\n'
        '                                         in do_nucleo if not ok],\n'
        '                    "caidas_do_artefato": [rotulo for rotulo, ok, _\n'
        '                                           in do_artefato if not ok],\n'
        '                    "turnos": sessao.get("num_turns"),\n'
        '                    "segundos": round(parede, 1),\n'
        '                    "dolar": sessao.get("total_cost_usd")}\n'
        '\n'
        '\n'
        'PASSOS = (\n'
        '    ("medir", TITULO_MEDIR, medir),\n'
        '    ("provar", TITULO_PROVAR, provar),\n'
        '    ("simular", TITULO_SIMULAR, simular),\n'
        ')\n'
        '\n'
        'NUMEROS = {\n'
        '    "largada": ("medir", "largada"),\n'
        '    "adiado": ("medir", "adiado"),\n'
        '    "paginas": ("medir", "paginas"),\n'
        '    "ganchos": ("medir", "ganchos"),\n'
        '    "subagentes": ("medir", "subagentes"),\n'
        '    "vocabulario-aberto": ("medir", "vocabulario_aberto"),\n'
        '    "vocabulario-nao-medido": ("medir", "vocabulario_nao_medido"),\n'
        '    "subagentes-sem-coleira": ("medir", "subagentes_sem_coleira"),\n'
        '    "skills-acima-do-teto": ("medir", "skills_acima_do_teto"),\n'
        '    "injetado-por-gancho": ("medir", "injetado_por_gancho"),\n'
        '    "ganchos-nao-medidos": ("medir", "ganchos_nao_medidos"),\n'
        '    "instrumentos-que-caem": ("provar", "caem"),\n'
        '    "ganchos-sem-teste": ("provar", "sem_teste"),\n'
        '    "acertos-da-simulacao": ("simular", "acertos"),\n'
        '    "regras-da-camada": ("medir", "regras"),\n'
        '}\n'
        '\n'
        '\n'
        'PROVAS = {\n'
        '    "medir": (("a largada que toda sessão paga, em bytes", "largada"),\n'
        '              ("o corpo de skill adiado, em bytes", "adiado"),\n'
        '              ("páginas de conhecimento", "paginas")),\n'
        '    "provar": (("instrumentos que caem", "instrumentos-que-caem"),),\n'
        '    "simular": (("as regras que o gabarito da simulação cobra",\n'
        '                 "regras-da-camada"),),\n'
        '}\n'
        'SUPOSTO_DA_SIMULACAO = (\n'
        '    "a sessão acertou {acertos} de {casos} checagens, em {turnos} turnos, "\n'
        '    "{segundos}s e US$ {dolar}. Este número NÃO entra em provado: é uma "\n'
        '    "sessão de verdade, e re-executar dá outro resultado.")\n'
        'SUPOSTO_SEM_SIMULACAO = ("a simulação não rodou: falta o claude no PATH ou o "\n'
        '                         "nucleo/regras.json.")\n'
        'SUPOSTO_DO_ARTEFATO = (\n'
        '    "checagem do artefato que a sessão errou, e que NÃO derruba a etapa "\n'
        '    "porque oscila entre execuções: {}.")\n'
        'VEREDITO_SEGUE = "segue"\n'
        'VEREDITO_PARA = "para"\n'
        'COMANDO_DO_NUMERO = "{} .agents/camada/camada.py --numero {}"\n'
        'FALTA_DO_PASSO = "{}: {}"\n'
        'PROXIMO_DO_PASSO = ("Leia a evidência, conserte o que o número acusa e "\n'
        '                    "reexecute esta etapa.")\n'
        '\n'
        '\n'
        'def julgar_a_simulacao(resumo: dict) -> tuple:\n'
        '    if not resumo.get("rodou"):\n'
        '        return [], [SUPOSTO_SEM_SIMULACAO]\n'
        '    suposto = [SUPOSTO_DA_SIMULACAO.format(\n'
        '        acertos=resumo["acertos"], casos=resumo["casos"],\n'
        '        turnos=resumo["turnos"], segundos=resumo["segundos"],\n'
        '        dolar=f"{resumo[\'dolar\'] or 0:.4f}")]\n'
        '    faltas = []\n'
        '    if resumo["certas_do_nucleo"] < resumo["casos_do_nucleo"]:\n'
        '        faltas.append(FALTA_DO_PASSO.format(\n'
        '            "checagens determinísticas que a sessão errou",\n'
        '            ", ".join(resumo.get("caidas_do_nucleo") or [])\n'
        '            or resumo["casos_do_nucleo"] - resumo["certas_do_nucleo"]))\n'
        '    if resumo["caidas_do_artefato"]:\n'
        '        suposto.append(SUPOSTO_DO_ARTEFATO.format(\n'
        '            ", ".join(resumo["caidas_do_artefato"])))\n'
        '    return faltas, suposto\n'
        '\n'
        '\n'
        'def evidencia(raiz: Path, passo: str) -> dict:\n'
        '    resumo = rodar_passos(raiz, {passo}, calado=True)[passo]\n'
        '    provado, faltas = [], []\n'
        '    for afirmacao, chave in PROVAS[passo]:\n'
        '        comando = COMANDO_DO_NUMERO.format(\n'
        '            interpretador_com_nome_portatil(), chave)\n'
        '        codigo, saida = corre(f\'cd "{raiz}" && {comando}\')\n'
        '        provado.append({"afirmacao": afirmacao, "comando": comando,\n'
        '                        "saida": saida})\n'
        '        if codigo != 0:\n'
        '            faltas.append(FALTA_DO_PASSO.format(chave, saida[:120]))\n'
        '    if passo == "provar" and resumo.get("caem"):\n'
        '        faltas.append(FALTA_DO_PASSO.format(\n'
        '            "instrumentos que caem", resumo["caem"]))\n'
        '    suposto = []\n'
        '    if passo == "simular":\n'
        '        do_simular, suposto = julgar_a_simulacao(resumo)\n'
        '        faltas += do_simular\n'
        '    dado = {"veredito": VEREDITO_PARA if faltas else VEREDITO_SEGUE,\n'
        '            "provado": provado, "suposto": suposto, "faltas": faltas}\n'
        '    if faltas:\n'
        '        dado["proximo"] = PROXIMO_DO_PASSO\n'
        '    return dado\n'
        '\n'
        '\n'
        'def rodar_passos(raiz: Path, escolhidos: set, calado: bool) -> dict:\n'
        '    resumo = {}\n'
        '    for nome, titulo, passo in PASSOS:\n'
        '        if escolhidos and nome not in escolhidos:\n'
        '            continue\n'
        '        linhas, dados = passo(raiz)\n'
        '        if not calado:\n'
        '            print(f"\\n{titulo}")\n'
        '            for linha in linhas:\n'
        '                print(linha)\n'
        '        resumo[nome] = dados\n'
        '    return resumo\n'
        '\n'
        '\n'
        'def um_numero(raiz: Path, chave: str) -> int:\n'
        '    if chave not in NUMEROS:\n'
        '        sys.exit(NUMERO_DESCONHECIDO.format(chave, " ".join(sorted(NUMEROS))))\n'
        '    passo, campo = NUMEROS[chave]\n'
        '    resumo = rodar_passos(raiz, {passo}, calado=True)\n'
        '    valor = resumo[passo].get(campo)\n'
        '    print(NUMERO_NAO_MEDIDO if valor is None else valor)\n'
        '    return 0\n'
        '\n'
        '\n'
        'def ligar_ganchos(raiz: Path, caminhos: list) -> None:\n'
        '    blocos = [{CHAVE_DOS_GANCHOS: [{\n'
        '        "type": "command",\n'
        '        CHAVE_DO_COMANDO: f\'python "{RAIZ_NO_COMANDO}/{c}"\'}]}\n'
        '        for c in caminhos]\n'
        '    destino = raiz / ARQUIVO_SETTINGS\n'
        '    destino.parent.mkdir(parents=True, exist_ok=True)\n'
        '    destino.write_text(\n'
        '        json.dumps({CHAVE_DOS_GANCHOS: {EVENTO_DE_ABERTURA: blocos}}),\n'
        '        encoding="utf-8")\n'
        '\n'
        '\n'
        'def testar() -> int:\n'
        '    falhas, casos = [], []\n'
        '\n'
        '    def caso(rotulo, passou):\n'
        '        casos.append(rotulo)\n'
        '        if not passou:\n'
        '            falhas.append(rotulo)\n'
        '\n'
        '    with tempfile.TemporaryDirectory() as pasta:\n'
        '        raiz = Path(pasta)\n'
        '        (raiz / "AGENTS.md").write_text("abc\\n", encoding="utf-8")\n'
        '        (raiz / PASTA_DO_CONHECIMENTO).mkdir()\n'
        '        (raiz / PASTA_DOS_GANCHOS).mkdir(parents=True)\n'
        '        skill = raiz / PASTA_DAS_SKILLS_FONTE / "s"\n'
        '        skill.mkdir(parents=True)\n'
        '        (skill / "SKILL.md").write_text(\n'
        '            "---\\nname: s\\ndescription: faz algo\\n---\\n\\ncorpo longo aqui\\n",\n'
        '            encoding="utf-8")\n'
        '\n'
        '        _, dados = medir(raiz)\n'
        '        caso("a largada soma instruções mais catálogo, nunca o corpo",\n'
        '             dados["largada"] == 4 + len("- s: faz algo\\n".encode()))\n'
        '\n'
        '        injecao = "regra que o gancho injeta\\n"\n'
        '        (raiz / "gancho.py").write_text(\n'
        '            "import json\\n"\n'
        '            "print(json.dumps({\'hookSpecificOutput\': "\n'
        '            "{\'additionalContext\': %r}}))\\n" % injecao,\n'
        '            encoding="utf-8")\n'
        '        (raiz / ".claude").mkdir(exist_ok=True)\n'
        '        (raiz / ".claude" / "settings.json").write_text(\n'
        '            json.dumps({"hooks": {"SessionStart": [{"hooks": [\n'
        '                {"type": "command", "command":\n'
        '                 f\'{INTERPRETADOR_NO_SHELL} "${{CLAUDE_PROJECT_DIR}}/gancho.py"\'}]}]}}),\n'
