        "            f'{INSTALADOR_DE_MENTIRA}MOLDE = '\n"
        '            \'{"so_o_instalador_cita": 4}\\n\', encoding="utf-8")\n'
        '        caso("o instalador não conta como leitor: a carga dele cita tudo",\n'
        '             \'"so_o_instalador_cita"\' in\n'
        '             (raiz / INSTALADOR).read_text(encoding="utf-8")\n'
        '             and chaves(raiz) == 1)\n'
        '\n'
        '        (raiz / ARQUIVO_DE_CONFIGURACAO).write_text("{", encoding="utf-8")\n'
