        '    return {um["id"] for um in _achados_do_corpo(corpo)}\n'
        '\n'
        '\n'
        'def a_linha(corpo: str, identidade: str) -> dict:\n'
        '    achadas = [um for um in _achados_do_corpo(corpo)\n'
        '               if um["id"] == identidade]\n'
        '    return achadas[0] if achadas else {}\n'
        '\n'
        '\n'
        'def recusa_do_bloco(corpo: str, issue) -> str:\n'
        '    partes = partes_do_corpo(corpo)\n'
        '    if not partes:\n'
        '        return RECUSA_SEM_BLOCO.format(abre=MARCA_ABRE, fecha=MARCA_FECHA)\n'
        '    perdidas = linhas_que_nao_leio(partes[1])\n'
        '    if perdidas:\n'
        '        return RECUSA_LINHA_QUE_NAO_LEIO.format(issue=issue,\n'
        '                                                formato=LINHA_DO_ACHADO,\n'
        '                                                linha=perdidas[0])\n'
        '    return ""\n'
        '\n'
        '\n'
        'def gravar_relendo(endereco: dict, corpo: str, refazer, o_que) -> tuple:\n'
        '    esperadas = _identidades_do_corpo(refazer(corpo, o_que))\n'
        '    tiradas = _identidades_do_corpo(corpo) - esperadas\n'
        '    gravacoes = 0\n'
        '    while True:\n'
        '        atual, erro = ler_corpo(endereco)\n'
        '        if erro:\n'
        '            return gravacoes, set(), erro\n'
        '        erro = recusa_do_bloco(atual, endereco["issue"])\n'
        '        if erro:\n'
        '            return gravacoes, set(), erro\n'
        '        presentes = _identidades_do_corpo(atual)\n'
        '        divergentes = (esperadas - presentes) | (tiradas & presentes)\n'
        '        proposto = refazer(atual, o_que)\n'
        '        if proposto == atual or gravacoes == TENTATIVAS_DE_GRAVACAO:\n'
        '            return gravacoes, divergentes, ""\n'
        '        esperadas |= _identidades_do_corpo(proposto)\n'
        '        tiradas |= presentes - _identidades_do_corpo(proposto)\n'
        '        erro = gravar_corpo(endereco, proposto)\n'
        '        if erro:\n'
        '            return gravacoes, set(), erro\n'
        '        gravacoes += 1\n'
        '\n'
        '\n'
        'def por_na_caixa(endereco: dict, novo: dict, ensaio: bool = False) -> tuple:\n'
        '    corpo, erro = ler_corpo(endereco)\n'
        '    if erro:\n'
        '        return 2, erro\n'
        '    erro = recusa_do_bloco(corpo, endereco["issue"])\n'
        '    if erro:\n'
        '        return 2, erro\n'
        '    if ensaio:\n'
        '        return 0, RECADO_DO_ENSAIO.format(\n'
        '            issue=endereco["issue"],\n'
        '            miolo=partes_do_corpo(corpo_com(corpo, novo))[1])\n'
        '    ja_estava = any(um["id"] == novo["id"] for um in _achados_do_corpo(corpo))\n'
        '    gravacoes, divergentes, erro = gravar_relendo(endereco, corpo, corpo_com,\n'
        '                                                  novo)\n'
        '    if erro:\n'
        '        return 2, erro\n'
        '    if divergentes:\n'
        '        return 2, NAO_ESTA_LA.format(issue=endereco["issue"],\n'
        '                                     id=", ".join(sorted(divergentes)))\n'
        '    if not gravacoes:\n'
        '        return 0, RECADO_JA_ESTAVA.format(issue=endereco["issue"],\n'
        '                                          id=novo["id"])\n'
        '    recado = RECADO_ATUALIZADO if ja_estava else RECADO_POSTO\n'
        '    return 0, recado.format(issue=endereco["issue"], id=novo["id"])\n'
        '\n'
        '\n'
        'def rodar(tipo: str, identidade: str, assunto: str, quando: str,\n'
        '          cwd: str = "", ensaio: bool = False, quadro: str = "",\n'
