        '    "caminho: trabalhe na sua branch e peça a promoção ao dono, que roda o "\n'
        '    "comando ele mesmo. Se esta branch não deveria estar protegida, tire o "\n'
        '    "nome de .claude/branches-protegidas.txt."\n'
        ')\n'
        '\n'
        'FALHA_DEVIA_BARRAR = "  DEVIA BARRAR e passou — {}: {}"\n'
        'FALHA_DEVIA_PASSAR = "  DEVIA PASSAR e barrou — {}: {} ({})"\n'
        'FALHA_DEVIA_BARRAR_SEM_AUTORIZACAO = (\n'
        '    "  DEVIA BARRAR sem autorização e passou — {}")\n'
        'FALHA_DEVIA_PASSAR_COM_AUTORIZACAO = (\n'
        '    "  DEVIA PASSAR com autorização e barrou — {}")\n'
        'FALHA_RECUSA_NAO_ENSINA = "  a recusa não ensina — {}"\n'
        'FALHA_FORCA_MESMO_AUTORIZADO = (\n'
        '    "  DEVIA BARRAR: força em protegida, mesmo autorizado")\n'
        'RESUMO_FALHOU = "FALHOU: {} de {} casos"\n'
        'RESUMO_OK = "OK: {} casos — {} barrados, {} liberados"\n'
        '\n'
        '\n'
        'def cortar_respeitando_aspas(comando: str):\n'
        '    segmentos, atual, aspa_aberta = [], [], None\n'
        '    i = 0\n'
        '    while i < len(comando):\n'
        '        c = comando[i]\n'
        '        if aspa_aberta == ASPA_SIMPLES:\n'
        '            atual.append(c)\n'
        '            aspa_aberta = None if c == ASPA_SIMPLES else aspa_aberta\n'
        '            i += 1\n'
        '        elif aspa_aberta == ASPA_DUPLA and c == ASPA_DUPLA:\n'
        '            atual.append(c)\n'
        '            aspa_aberta = None\n'
        '            i += 1\n'
        '        elif aspa_aberta is None and c in ASPAS:\n'
        '            atual.append(c)\n'
        '            aspa_aberta = c\n'
        '            i += 1\n'
        '        elif corte := (EXPANSAO_QUE_ASPA_DUPLA_NAO_SEGURA if aspa_aberta\n'
        '                       else SEPARADORES_DE_COMANDO).match(comando, i):\n'
        '            segmentos.append("".join(atual))\n'
        '            atual = []\n'
        '            i = corte.end()\n'
        '        else:\n'
        '            atual.append(c)\n'
        '            i += 1\n'
        '    if aspa_aberta is not None:\n'
        '        return None\n'
        '    segmentos.append("".join(atual))\n'
        '    return segmentos\n'
        '\n'
        '\n'
        'def separar(comando: str) -> list:\n'
        '    sem_documento = DOCUMENTO_LITERAL_QUE_NAO_EXPANDE.sub(" ", comando)\n'
        '    segmentos = cortar_respeitando_aspas(sem_documento)\n'
        '    aspas_nao_fecharam = segmentos is None\n'
        '    if aspas_nao_fecharam:\n'
        '        return SEPARADORES_DE_COMANDO.split(sem_documento)\n'
        '    return segmentos\n'
        '\n'
        '\n'
        'def nomes_protegidos(raiz: Path) -> set:\n'
        '    arquivo = raiz / ARQUIVO_DE_BRANCHES_PROTEGIDAS\n'
        '    try:\n'
        '        linhas = arquivo.read_text(encoding="utf-8").splitlines()\n'
        '    except OSError:\n'
        '        return set(PROTEGIDAS_EMBUTIDAS)\n'
        '    nomes = {l.strip().lower() for l in linhas\n'
        '             if l.strip() and not l.strip().startswith(MARCA_DE_COMENTARIO)}\n'
        '    return nomes or set(PROTEGIDAS_EMBUTIDAS)\n'
        '\n'
        '\n'
        'def branch_de_destino_do_ref(ref: str) -> str:\n'
        '    ref = ref.strip().lstrip(PREFIXO_DE_FORCAR_POR_REFSPEC)\n'
        '    if PREFIXO_DE_APAGAR_POR_REFSPEC in ref:\n'
        '        ref = ref.split(PREFIXO_DE_APAGAR_POR_REFSPEC, 1)[1]\n'
        '    ref = PREFIXO_DE_REFS_DE_BRANCH.sub("", ref)\n'
        '    return ref.strip().lower()\n'
        '\n'
        '\n'
        'def e_git(token: str) -> bool:\n'
        '    return Path(token.replace("\\\\", "/")).name.lower() in NOMES_DO_GIT\n'
        '\n'
        '\n'
        'def e_gh(token: str) -> bool:\n'
        '    return Path(token).name.lower().removesuffix(EXTENSAO_EXE) == NOME_DO_GH\n'
        '\n'
        '\n'
        'def sem_o_par_de_aspas_que_envolve(token: str) -> str:\n'
        '    for aspa in (ASPA_DUPLA, ASPA_SIMPLES):\n'
        '        if len(token) >= 2 and token.startswith(aspa) and token.endswith(aspa):\n'
        '            return token[1:-1]\n'
        '    return token\n'
        '\n'
        '\n'
        'def partir_em_tokens(segmento: str) -> list:\n'
        '    try:\n'
        '        import shlex\n'
        '        tokens = shlex.split(segmento, posix=False)\n'
        '    except ValueError:\n'
        '        tokens = segmento.split()\n'
        '    return [sem_o_par_de_aspas_que_envolve(t) for t in tokens]\n'
        '\n'
        '\n'
        'def indice_do_verbo(tokens: list) -> int:\n'
        '    i = 1\n'
        '    while i < len(tokens):\n'
        '        t = tokens[i]\n'
        '        if t in BANDEIRAS_GLOBAIS_QUE_COMEM_O_TOKEN_SEGUINTE:\n'
        '            i += 2\n'
        '            continue\n'
        '        colada_por_igual = any(\n'
        '            t.startswith(g + "=")\n'
        '            for g in BANDEIRAS_GLOBAIS_QUE_COMEM_O_TOKEN_SEGUINTE)\n'
        '        if colada_por_igual or t in BANDEIRAS_GLOBAIS_SIMPLES:\n'
        '            i += 1\n'
        '            continue\n'
        '        if t.startswith("-"):\n'
        '            i += 1\n'
        '            continue\n'
        '        return i\n'
        '    return SEM_VERBO\n'
        '\n'
        '\n'
        'def verbo_e_resto(tokens: list):\n'
        '    i = indice_do_verbo(tokens)\n'
        '    if i == SEM_VERBO:\n'
        '        return None, []\n'
        '    return tokens[i].lower(), tokens[i + 1:]\n'
        '\n'
        '\n'
        'def branch_atual(alvo: Path):\n'
        '    try:\n'
        '        r = subprocess.run(COMANDO_DA_BRANCH_ATUAL, cwd=alvo,\n'
        '                           capture_output=True, text=True,\n'
        '                           timeout=TEMPO_LIMITE_DO_GIT)\n'
        '    except (OSError, subprocess.SubprocessError):\n'
        '        return None\n'
        '    nome = r.stdout.strip().lower()\n'
        '    return nome if r.returncode == 0 and nome and nome != HEAD_SOLTA else None\n'
        '\n'
        '\n'
        'def branches_conhecidas(alvo: Path) -> set:\n'
        '    try:\n'
        '        r = subprocess.run(COMANDO_DAS_BRANCHES, cwd=alvo,\n'
        '                           capture_output=True, text=True,\n'
        '                           timeout=TEMPO_LIMITE_DO_GIT)\n'
        '    except (OSError, subprocess.SubprocessError):\n'
        '        return set()\n'
        '    if r.returncode != 0:\n'
        '        return set()\n'
        '    return {linha.strip().lower() for linha in r.stdout.splitlines()\n'
        '            if linha.strip()}\n'
        '\n'
        '\n'
        'def branch_pedida_ao_checkout(resto: list):\n'
        '    if FIM_DAS_BANDEIRAS in resto:\n'
        '        return "", False\n'
        '    espera_o_nome = False\n'
        '    for token in resto:\n'
        '        if espera_o_nome:\n'
        '            return token.lower(), True\n'
        '        if token.lower() in BANDEIRAS_QUE_CRIAM_BRANCH:\n'
        '            espera_o_nome = True\n'
        '            continue\n'
        '        if token.startswith("-"):\n'
        '            continue\n'
        '        return token.lower(), False\n'
        '    return "", False\n'
        '\n'
        '\n'
        'def a_linha_so_encadeia(comando: str) -> bool:\n'
        '    return not SEPARADORES_DE_COMANDO.search(\n'
        '        comando.replace(SEPARADOR_QUE_ENCADEIA, " "))\n'
        '\n'
        '\n'
        'def branch_depois_do_segmento(tokens: list, aqui: str, conhecidas: set) -> str:\n'
        '    if not tokens or not e_git(tokens[0]):\n'
        '        return aqui\n'
        '    verbo, resto = verbo_e_resto(tokens)\n'
        '    if verbo not in VERBOS_QUE_TROCAM_DE_BRANCH:\n'
        '        return aqui\n'
        '    nome, criada = branch_pedida_ao_checkout(resto)\n'
        '    if not nome:\n'
        '        return aqui\n'
        '    return nome if criada or nome in conhecidas else aqui\n'
        '\n'
        '\n'
        'def cd_que_abre_o_comando(comando: str) -> str:\n'
        '    segmentos = separar(comando)\n'
        '    primeiro = segmentos[0].strip() if segmentos else ""\n'
        '    tokens = partir_em_tokens(primeiro)\n'
        '    if len(tokens) >= 2 and Path(tokens[0]).name == COMANDO_CD:\n'
        '        return tokens[1]\n'
        '    return ""\n'
        '\n'
        '\n'
        'def comando_traz_git_init(comando: str) -> bool:\n'
        '    for segmento in separar(comando):\n'
        '        tokens = partir_em_tokens(segmento.strip())\n'
        '        if not tokens or not e_git(tokens[0]):\n'
        '            continue\n'
        '        i = indice_do_verbo(tokens)\n'
        '        if i != SEM_VERBO and tokens[i].lower() == VERBO_INIT:\n'
        '            return True\n'
        '    return False\n'
        '\n'
        '\n'
        'def repositorio_que_o_comando_muda(onde: str, padrao: Path,\n'
        '                                   comando: str = "") -> Path:\n'
        '    if (destino := cd_que_abre_o_comando(comando)):\n'
        '        alvo = Path(destino)\n'
        '        onde = str(alvo if alvo.is_absolute() else Path(onde or ".") / alvo)\n'
        '    if not onde:\n'
        '        return padrao\n'
        '    atual = Path(onde)\n'
        '    try:\n'
        '        atual = atual.resolve(strict=False)\n'
        '    except OSError:\n'
        '        return padrao\n'
        '    if comando_traz_git_init(comando):\n'
        '        return atual\n'
        '    while True:\n'
        '        if (atual / PASTA_DO_GIT).exists():\n'
        '            return atual\n'
        '        if atual.parent == atual:\n'
        '            return padrao\n'
        '        atual = atual.parent\n'
        '\n'
        '\n'
        'def autorizacoes(raiz: Path) -> dict:\n'
        '    permitido = dict(OMISSAO_NAO_E_PERMISSAO)\n'
        '    try:\n'
        '        dado = json.loads(\n'
        '            (raiz / ARQUIVO_CONFIGURACAO).read_text(encoding="utf-8"))\n'
        '    except (OSError, ValueError):\n'
        '        return permitido\n'
        '    declarado = (dado.get(CHAVE_DAS_AUTORIZACOES)\n'
        '                 if isinstance(dado, dict) else None)\n'
        '    if not isinstance(declarado, dict):\n'
        '        return permitido\n'
        '    for acao in permitido:\n'
        '        valor = declarado.get(acao)\n'
        '        if isinstance(valor, bool):\n'
        '            permitido[acao] = valor\n'
        '    return permitido\n'
        '\n'
        '\n'
        'def acao_do_comando(tokens: list) -> str:\n'
        '    if not tokens:\n'
        '        return SEM_ACAO\n'
        '    programa = Path(tokens[0]).name.lower().removesuffix(EXTENSAO_EXE)\n'
        '    if programa not in PROGRAMAS_QUE_ACIONAM:\n'
        '        return SEM_ACAO\n'
        '    i = indice_do_verbo(tokens)\n'
        '    if i == SEM_VERBO:\n'
        '        return SEM_ACAO\n'
        '    primeiro = tokens[i].lower()\n'
        '    segundo = tokens[i + 1].lower() if i + 1 < len(tokens) else ""\n'
        '    if segundo in SUBVERBOS_QUE_SO_PEDEM.get(primeiro, frozenset()):\n'
        '        return SEM_ACAO\n'
        '    e_do_git = Path(tokens[0]).name.lower() in NOMES_DO_GIT\n'
        '    if primeiro == VERBO_MERGE and e_do_git:\n'
        '        return ACAO_COMMIT\n'
        '    for acao, verbos in VERBOS_POR_ACAO.items():\n'
        '        if primeiro in verbos:\n'
        '            return acao\n'
        '    return SEM_ACAO\n'
        '\n'
        '\n'
        'def recusa_do_verbo_branch(bandeiras: set, atingidas: list) -> str:\n'
        '    apaga = bool(bandeiras & BANDEIRAS_DE_APAGAR)\n'
        '    renomeia = bool(bandeiras & BANDEIRAS_DE_RENOMEAR)\n'
        '    if (apaga or renomeia) and atingidas:\n'
        '        return MOTIVO_BRANCH_PROTEGIDA.format(\n'
        '            ACAO_APAGAR if apaga else ACAO_RENOMEAR, atingidas[0])\n'
        '    return SEM_RECUSA\n'
        '\n'
        '\n'
        'def recusa_do_verbo_push(bandeiras: set, resto: list, refs: list,\n'
        '                         atingidas: list, protegidas: set, alvo: Path,\n'
        '                         aqui: str = None) -> str:\n'
        '    if BANDEIRA_DE_ESPELHO in bandeiras:\n'
        '        return MOTIVO_ESPELHO\n'
        '\n'
        '    apaga = bool(bandeiras & BANDEIRAS_DE_APAGAR)\n'
        '    forca = bool(bandeiras & BANDEIRAS_DE_FORCA) or any(\n'
        '        b.startswith(BANDEIRAS_DE_FORCA_COM_RESSALVA) for b in bandeiras)\n'
        '\n'
        '    def destinos_com_prefixo(prefixo):\n'
        '        return [branch_de_destino_do_ref(t) for t in resto\n'
        '                if not t.startswith("-") and t.startswith(prefixo)]\n'
        '\n'
        '    for nome in destinos_com_prefixo(PREFIXO_DE_APAGAR_POR_REFSPEC):\n'
        '        if nome in protegidas:\n'
        '            return MOTIVO_APAGAR_POR_REFSPEC.format(nome)\n'
        '    for nome in destinos_com_prefixo(PREFIXO_DE_FORCAR_POR_REFSPEC):\n'
        '        if nome in protegidas:\n'
        '            return MOTIVO_FORCAR_POR_REFSPEC.format(nome)\n'
        '    if apaga and atingidas:\n'
        '        return MOTIVO_BRANCH_PROTEGIDA.format(ACAO_APAGAR, atingidas[0])\n'
        '    if forca and atingidas:\n'
        '        return MOTIVO_REESCREVER_HISTORIA.format(atingidas[0])\n'
        '    if forca and not refs:\n'
        '        atual = branch_atual(alvo) if aqui is None else aqui\n'
        '        if atual in protegidas:\n'
        '            return MOTIVO_REESCREVER_A_BRANCH_ATUAL.format(atual)\n'
        '    return SEM_RECUSA\n'
        '\n'
        '\n'
        'def branches_por_incorporacao(raiz: Path) -> set:\n'
        '    try:\n'
        '        dado = json.loads(\n'
        '            (raiz / ARQUIVO_CONFIGURACAO).read_text(encoding="utf-8"))\n'
        '    except (OSError, ValueError):\n'
        '        return set()\n'
        '    declarado = (dado.get(CHAVE_POR_INCORPORACAO)\n'
        '                 if isinstance(dado, dict) else None)\n'
        '    if not isinstance(declarado, list):\n'
        '        return set()\n'
        '    return {str(nome).strip().lower() for nome in declarado if str(nome).strip()}\n'
        '\n'
        '\n'
        'def motivo_da_recusa(comando: str, protegidas: set, alvo: Path,\n'
        '                     permitido: dict = None, aqui: str = None,\n'
        '                     por_incorporacao: set = None, conhecidas: set = None):\n'
        '    permitido = OMISSAO_NAO_E_PERMISSAO if permitido is None else permitido\n'
        '    aqui = branch_atual(alvo) if aqui is None else aqui\n'
        '    por_incorporacao = (branches_por_incorporacao(alvo)\n'
        '                        if por_incorporacao is None else por_incorporacao)\n'
        '    conhecidas = (branches_conhecidas(alvo) if conhecidas is None\n'
        '                  else conhecidas)\n'
        '    recusa_por_autorizacao_pendente = SEM_RECUSA\n'
        '    segue_a_branch = a_linha_so_encadeia(comando)\n'
        '    for segmento in separar(comando):\n'
        '        tokens = partir_em_tokens(segmento.strip())\n'
        '        if not tokens or not (e_git(tokens[0]) or e_gh(tokens[0])):\n'
        '            continue\n'
        '        if segue_a_branch:\n'
        '            aqui = branch_depois_do_segmento(tokens, aqui, conhecidas)\n'
        '\n'
        '        acao = acao_do_comando(tokens)\n'
        '        if acao == ACAO_COMMIT and aqui in por_incorporacao:\n'
        '            return MOTIVO_GRAVA_EM_PROTEGIDA.format(acao, aqui)\n'
        '        if (acao and not permitido.get(acao, False)\n'
        '                and not recusa_por_autorizacao_pendente):\n'
        '            recusa_por_autorizacao_pendente = MOTIVO_SEM_AUTORIZACAO.format(\n'
        '                acao, acao, ARQUIVO_CONFIGURACAO)\n'
        '\n'
        '        verbo, resto = verbo_e_resto(tokens)\n'
        '        if verbo not in VERBOS_QUE_MEXEM_EM_BRANCH:\n'
        '            continue\n'
        '\n'
        '        bandeiras = {t.lower() for t in resto if t.startswith("-")}\n'
        '        refs = [branch_de_destino_do_ref(t)\n'
        '                for t in resto if not t.startswith("-")]\n'
        '        atingidas = [r for r in refs if r in protegidas]\n'
        '\n'
        '        recusa = (recusa_do_verbo_branch(bandeiras, atingidas)\n'
        '                  if verbo == VERBO_BRANCH else\n'
        '                  recusa_do_verbo_push(bandeiras, resto, refs, atingidas,\n'
        '                                       protegidas, alvo, aqui))\n'
        '        if recusa:\n'
        '            return recusa\n'
        '    return recusa_por_autorizacao_pendente or None\n'
        '\n'
        '\n'
        'ARQUIVO_EXECUTOR = "nucleo/executor.json"\n'
        'CHAVE_DOS_PROJETOS = "projetos"\n'
        'CHAVE_DO_REPOSITORIO = "repositorio"\n'
        'CHAVE_DO_SO_LEITURA = "somente_leitura"\n'
        'CHAVE_DAS_AUTORIZACOES_DO_VIZINHO = "autorizacoes"\n'
        '\n'
        '\n'
        'def _projetos(raiz: Path) -> dict:\n'
        '    try:\n'
        '        dado = json.loads(\n'
        '            (raiz / ARQUIVO_EXECUTOR).read_text(encoding="utf-8"))\n'
        '    except (OSError, ValueError):\n'
        '        return {}\n'
        '    projetos = (dado or {}).get(CHAVE_DOS_PROJETOS) or {}\n'
        '    return projetos if isinstance(projetos, dict) else {}\n'
        '\n'
        '\n'
        'def _projeto_do_repositorio(raiz: Path, nome: str) -> dict:\n'
        '    for projeto in _projetos(raiz).values():\n'
        '        if isinstance(projeto, dict) \\\n'
        '                and projeto.get(CHAVE_DO_REPOSITORIO) == nome:\n'
        '            return projeto\n'
        '    return {}\n'
        '\n'
        '\n'
        'def e_somente_leitura(raiz: Path, alvo: Path) -> bool:\n'
        '    projeto = _projeto_do_repositorio(raiz, Path(alvo).name)\n'
        '    return bool(projeto.get(CHAVE_DO_SO_LEITURA))\n'
        '\n'
        '\n'
        'def autorizacoes_do_alvo(raiz: Path, alvo: Path) -> dict:\n'
        '    if Path(alvo) == Path(raiz):\n'
        '        return autorizacoes(alvo)\n'
        '    declarado = _projeto_do_repositorio(raiz, Path(alvo).name).get(\n'
        '        CHAVE_DAS_AUTORIZACOES_DO_VIZINHO)\n'
        '    if isinstance(declarado, dict):\n'
        '        permitido = dict(OMISSAO_NAO_E_PERMISSAO)\n'
        '        for acao in permitido:\n'
        '            if isinstance(declarado.get(acao), bool):\n'
        '                permitido[acao] = declarado[acao]\n'
        '        return permitido\n'
        '    return autorizacoes(alvo)\n'
        '\n'
        '\n'
        'def raiz_do_projeto_nunca_o_cwd() -> Path:\n'
        '    declarada = os.environ.get(VARIAVEL_DA_RAIZ_DO_PROJETO)\n'
        '    if declarada:\n'
        '        return Path(declarada)\n'
        '    return Path(__file__).resolve().parents[NIVEIS_DO_GANCHO_ATE_A_RAIZ]\n'
        '\n'
        '\n'
        'def recusa_por_nao_entender(falha) -> int:\n'
        '    print(json.dumps({"hookSpecificOutput": {\n'
        '        "hookEventName": EVENTO_ANTES_DA_FERRAMENTA,\n'
        '        "permissionDecision": DECISAO_DE_NEGAR,\n'
        '        "permissionDecisionReason": RECUSA_SEM_ENTENDER.format(\n'
        '            type(falha).__name__, falha),\n'
        '    }}, ensure_ascii=False))\n'
        '    return SILENCIO\n'
        '\n'
        '\n'
        'def decidir() -> int:\n'
        '    try:\n'
        '        entrada = json.load(sys.stdin)\n'
        '        comando = entrada.get("tool_input", {}).get("command", "")\n'
        '        onde = entrada.get("cwd") or ""\n'
        '    except (json.JSONDecodeError, AttributeError, TypeError,\n'
        '            ValueError) as falha:\n'
        '        return recusa_por_nao_entender(falha)\n'
        '\n'
        '    baixo = (comando or "").lower()\n'
        '    nada_de_git_nem_de_gh = (MARCA_DO_GIT not in baixo\n'
        '                             and MARCA_DO_GH not in baixo)\n'
        '    if not comando or nada_de_git_nem_de_gh:\n'
        '        return SILENCIO\n'
        '\n'
        '    raiz = raiz_do_projeto_nunca_o_cwd()\n'
        '    alvo = repositorio_que_o_comando_muda(onde, raiz, comando)\n'
        '    if e_somente_leitura(raiz, alvo):\n'
        '        return SILENCIO\n'
        '    motivo = motivo_da_recusa(\n'
        '        comando, nomes_protegidos(alvo), alvo,\n'
        '        autorizacoes_do_alvo(raiz, alvo), None,\n'
        '        branches_por_incorporacao(alvo))\n'
        '    if not motivo:\n'
