        '\n'
        '\n'
        '\n'
        'def recusou_sem_entender(falha) -> bool:\n'
        '    import contextlib\n'
        '    import io\n'
        '    saida = io.StringIO()\n'
        '    with contextlib.redirect_stdout(saida):\n'
        '        recusa_por_nao_entender(falha)\n'
