        'MARCA_DE_ETAPA_NO_AMBIENTE = "ENCADEADOR_ETAPA"\n'
        'VARIAVEL_DA_RAIZ_DO_PROJETO = "CLAUDE_PROJECT_DIR"\n'
        '\n'
        'FERRAMENTAS_DE_ESCRITA = ("Write", "Edit", "NotebookEdit")\n'
