        'def com_a_raiz_apontando_para(pasta: str, acao) -> None:\n'
        '    guardado = os.environ.get(VARIAVEL_DA_RAIZ_DO_PROJETO)\n'
        '    os.environ[VARIAVEL_DA_RAIZ_DO_PROJETO] = pasta\n'
        '    try:\n'
        '        acao()\n'
        '    finally:\n'
        '        if guardado is None:\n'
        '            os.environ.pop(VARIAVEL_DA_RAIZ_DO_PROJETO, None)\n'
        '        else:\n'
        '            os.environ[VARIAVEL_DA_RAIZ_DO_PROJETO] = guardado\n'
