        'def testar_a_evidencia_materializada(caso, falhas: list) -> None:\n'
        '    import shutil\n'
        '    import tempfile\n'
        '\n'
        '    raiz_real = Path(__file__).resolve().parents[NIVEIS_DO_GANCHO_ATE_A_RAIZ]\n'
