        '        segundo = pasta_evidencias / f"01-{ETAPA_EVIDENCIA}-c2.json"\n'
        '        de_metadata = pasta_evidencias / f"01-{ETAPA_EVIDENCIA}-c3.json"\n'
        '        caso("orienta materializa evidência c1", primeiro.is_file())\n'
        '        caso("veta materializa evidência c2 (ciclo pela contagem)",\n'
        '             segundo.is_file())\n'
        '        caso("o veto de metadata materializa evidência c3",\n'
        '             de_metadata.is_file())\n'
        '        if not (primeiro.is_file() and segundo.is_file()\n'
        '                and de_metadata.is_file()):\n'
        '            return\n'
        '\n'
        '        r1 = json.loads(primeiro.read_text(encoding="utf-8"))\n'
        '        r2 = json.loads(segundo.read_text(encoding="utf-8"))\n'
        '        r_metadata = json.loads(de_metadata.read_text(encoding="utf-8"))\n'
        '        caso("orienta é segue", r1.get("veredito") == VEREDITO_SEGUE)\n'
        '        caso("veta é para, com proximo",\n'
        '             r2.get("veredito") == VEREDITO_PARA and r2.get("proximo"))\n'
        '        caso("o veto de metadata é para, com proximo, e a afirmação diz que "\n'
        '             "chamou o endpoint",\n'
        '             r_metadata.get("veredito") == VEREDITO_PARA\n'
        '             and r_metadata.get("proximo")\n'
        '             and "metadata" in r_metadata["provado"][0]["afirmacao"])\n'
        '        prova = subprocess.run(\n'
        '            INTERPRETADOR_DE_SHELL + [r1["provado"][0]["comando"]],\n'
        '            capture_output=True, text=True, cwd=raiz_real)\n'
        '        caso("a prova do provado re-executa igual",\n'
        '             prova.stdout.strip() == r1["provado"][0]["saida"])\n'
        '        ambiente_limpo = {"PATH": "/usr/local/bin:/usr/bin:/bin"}\n'
        '        prova_limpa = subprocess.run(\n'
        '            INTERPRETADOR_DE_SHELL + [r1["provado"][0]["comando"]],\n'
        '            capture_output=True, text=True, cwd=raiz_real, env=ambiente_limpo)\n'
        '        caso("a prova re-executa com o mesmo interpretador que o "\n'
        '             "settings.json usa, mesmo sem o PATH da sessão",\n'
        '             prova_limpa.returncode == 0\n'
