        '\n'
        'def testar_comportamento(falhas: list) -> None:\n'
        '    def caso(rotulo, condicao):\n'
        '        if not condicao:\n'
        '            falhas.append(FALHA_DE_COMPORTAMENTO.format(rotulo))\n'
        '\n'
        '    testar_a_porta_da_leitura_direta(caso)\n'
        '    testar_a_forma_da_saida(caso)\n'
        '    testar_a_evidencia_materializada(caso, falhas)\n'
        '    testar_a_falha_aberta_sem_executor(caso)\n'
        '\n'
        '\n'
        'def testar() -> int:\n'
        '    falhas = []\n'
        '    for rotulo, comando in CASOS_QUE_ORIENTAM:\n'
        '        resposta, _ = decisao(comando)\n'
        '        if resposta != RESPOSTA_ORIENTA:\n'
        '            falhas.append(FALHA_DEVIA_ORIENTAR.format(\n'
        '                resposta or PALAVRA_CALOU, rotulo, comando))\n'
        '    for rotulo, comando in CASOS_QUE_VETAM:\n'
        '        resposta, _ = decisao(comando)\n'
        '        if resposta != RESPOSTA_VETA:\n'
        '            falhas.append(FALHA_DEVIA_VETAR.format(\n'
        '                resposta or PALAVRA_CALOU, rotulo, comando))\n'
        '    for rotulo, comando in CASOS_QUE_VETAM_POR_METADATA:\n'
        '        resposta, _ = decisao(comando)\n'
        '        if resposta != RESPOSTA_VETA_METADATA:\n'
        '            falhas.append(FALHA_DEVIA_VETAR.format(\n'
        '                resposta or PALAVRA_CALOU, rotulo, comando))\n'
        '    for rotulo, comando in CASOS_QUE_CALAM:\n'
        '        resposta, alvo = decisao(comando)\n'
        '        if resposta:\n'
        '            falhas.append(FALHA_DEVIA_CALAR.format(\n'
        '                resposta, rotulo, comando, alvo))\n'
        '    testar_comportamento(falhas)\n'
        '\n'
        '    vetam = len(CASOS_QUE_VETAM) + len(CASOS_QUE_VETAM_POR_METADATA)\n'
        '    total = len(CASOS_QUE_ORIENTAM) + vetam + len(CASOS_QUE_CALAM)\n'
        '    if falhas:\n'
        '        print(RESUMO_FALHOU.format(len(falhas)))\n'
        '        print("\\n".join(falhas))\n'
        '        return 1\n'
        '    print(RESUMO_OK.format(total, len(CASOS_QUE_ORIENTAM), vetam,\n'
