        'FALHA_COBROU_DE_MAIS = "CALA [{}]: cobrou — {}"\n'
        'FALHA_COMPORTAMENTO = "COMPORTAMENTO [{}]"\n'
        'RESUMO_FALHOU = "FALHOU: {} de {} casos"\n'
        'RESUMO_OK = "OK: {} casos — {} cobram, {} calam, {} de comportamento"\n'
        '\n'
        '\n'
        'def raiz_do_projeto_nunca_o_cwd() -> Path:\n'
        '    declarada = os.environ.get(VARIAVEL_DA_RAIZ_DO_PROJETO)\n'
        '    if declarada:\n'
        '        return Path(declarada)\n'
        '    return Path(__file__).resolve().parents[NIVEIS_DO_GANCHO_ATE_A_RAIZ]\n'
        '\n'
        '\n'
        'def branches_por_incorporacao(raiz: Path) -> set:\n'
        '    try:\n'
        '        dado = json.loads(\n'
        '            (raiz / ARQUIVO_CONFIGURACAO).read_text(encoding="utf-8"))\n'
        '    except (OSError, ValueError):\n'
        '        return set()\n'
        '    declarado = (dado.get(CHAVE_POR_INCORPORACAO)\n'
        '                 if isinstance(dado, dict) else None)\n'
        '    if not isinstance(declarado, list):\n'
        '        return set()\n'
        '    return {str(nome).strip().lower() for nome in declarado if str(nome).strip()}\n'
        '\n'
        '\n'
        'def branch_de_integracao(raiz: Path) -> str:\n'
        '    try:\n'
        '        dado = json.loads((raiz / ARQUIVO_EXECUTOR).read_text(encoding="utf-8"))\n'
        '    except (OSError, ValueError):\n'
        '        return ""\n'
        '    branches = dado.get(CHAVE_DAS_BRANCHES) if isinstance(dado, dict) else None\n'
        '    if not isinstance(branches, dict):\n'
        '        return ""\n'
        '    declarada = branches.get(CHAVE_DA_INTEGRACAO)\n'
        '    return str(declarada).strip() if declarada else ""\n'
        '\n'
        '\n'
        'def responde(comando: list, raiz: Path, tempo: int):\n'
        '    try:\n'
        '        pronto = subprocess.run(comando, cwd=raiz, capture_output=True,\n'
        '                                text=True, timeout=tempo)\n'
        '    except (OSError, subprocess.SubprocessError):\n'
        '        return NAO_MEDIDO\n'
        '    return pronto.returncode, (pronto.stdout or "").strip()\n'
        '\n'
        '\n'
        'def a_camada_julga(linha: str) -> bool:\n'
        '    caminho = linha[3:].strip().strip(\'"\')\n'
        '    return not caminho.lower().endswith(EXTENSOES_QUE_A_CAMADA_NAO_JULGA)\n'
        '\n'
        '\n'
        'def linhas_da_arvore_suja(raiz: Path) -> list:\n'
        '    return [l for l in _toda_a_sujeira(raiz) if a_camada_julga(l)]\n'
        '\n'
        '\n'
        'def linhas_que_a_camada_nao_julga(raiz: Path) -> list:\n'
        '    return [l for l in _toda_a_sujeira(raiz) if not a_camada_julga(l)]\n'
        '\n'
        '\n'
        'def _toda_a_sujeira(raiz: Path) -> list:\n'
        '    resposta = responde(COMANDO_DA_SUJEIRA, raiz, TEMPO_DO_GIT)\n'
        '    if resposta is NAO_MEDIDO or resposta[0] != 0:\n'
        '        return []\n'
        '    return [l for l in resposta[1].split("\\n") if l.strip()]\n'
        '\n'
        '\n'
        'def abertura_da_sessao(entrada: dict):\n'
        '    caminho = entrada.get(CHAVE_DO_TRANSCRITO) if isinstance(entrada, dict) else None\n'
        '    if not caminho:\n'
        '        return None\n'
        '    try:\n'
        '        with open(caminho, encoding="utf-8") as transcrito:\n'
        '            for _, linha in zip(range(LINHAS_LIDAS_DO_TRANSCRITO), transcrito):\n'
        '                instante = _instante_da_linha(linha)\n'
        '                if instante is not None:\n'
        '                    return instante\n'
        '    except OSError:\n'
        '        return None\n'
        '    return None\n'
        '\n'
        '\n'
        'def _instante_da_linha(linha: str):\n'
        '    try:\n'
        '        dado = json.loads(linha)\n'
        '    except ValueError:\n'
        '        return None\n'
        '    marcado = dado.get(CHAVE_DO_INSTANTE) if isinstance(dado, dict) else None\n'
        '    if not isinstance(marcado, str):\n'
        '        return None\n'
        '    try:\n'
        '        return datetime.fromisoformat(\n'
        '            marcado.replace(MARCA_DE_UTC, FUSO_UTC)).timestamp()\n'
        '    except ValueError:\n'
        '        return None\n'
        '\n'
        '\n'
        'def modificado_antes_da_abertura(raiz: Path, linha: str, abertura) -> bool:\n'
        '    if abertura is None:\n'
        '        return False\n'
        '    caminho = raiz / linha[3:].strip().strip(\'"\')\n'
        '    try:\n'
        '        return caminho.stat().st_mtime < abertura\n'
        '    except OSError:\n'
        '        return False\n'
        '\n'
        '\n'
        'def sessoes_vivas_ao_lado(pasta: Path, minha: str, agora: float) -> list:\n'
        '    if not pasta.is_dir():\n'
        '        return []\n'
        '    vivas = []\n'
        '    for transcrito in pasta.glob(f"*{EXTENSAO_DO_TRANSCRITO}"):\n'
        '        if transcrito.stem == minha:\n'
        '            continue\n'
        '        try:\n'
        '            idade = agora - transcrito.stat().st_mtime\n'
        '        except OSError:\n'
        '            continue\n'
        '        if 0 <= idade <= JANELA_DE_VIDA_EM_SEGUNDOS:\n'
        '            vivas.append((idade, transcrito.stem))\n'
        '    return sorted(vivas)[:QUANTAS_SESSOES_NOMEADAS]\n'
        '\n'
        '\n'
        'def arquivos_que_esta_sessao_escreveu(caminho, raiz: Path) -> set:\n'
        '    escritos = set()\n'
        '    if not caminho:\n'
        '        return escritos\n'
        '    try:\n'
        '        with open(caminho, encoding="utf-8") as transcrito:\n'
        '            for linha in transcrito:\n'
        '                try:\n'
        '                    dado = json.loads(linha)\n'
        '                except ValueError:\n'
        '                    continue\n'
        '                corpo = (dado.get("message") or {}).get("content")\n'
        '                for bloco in corpo if isinstance(corpo, list) else []:\n'
        '                    if not isinstance(bloco, dict):\n'
        '                        continue\n'
        '                    if bloco.get("name") in FERRAMENTAS_QUE_ESCREVEM:\n'
        '                        alvo = (bloco.get("input") or {}).get("file_path")\n'
        '                        if alvo:\n'
        '                            escritos.add(str(alvo))\n'
        '                    elif bloco.get("name") in FERRAMENTAS_DE_SHELL:\n'
        '                        escritos |= caminhos_que_o_shell_mexeu(\n'
        '                            (bloco.get("input") or {}).get(CAMPO_DO_COMANDO),\n'
        '                            raiz)\n'
        '    except OSError:\n'
        '        return escritos\n'
        '    return escritos\n'
        '\n'
        '\n'
        'def caminhos_que_o_shell_mexeu(comando, raiz: Path) -> set:\n'
        '    if not isinstance(comando, str) or not comando:\n'
        '        return set()\n'
        '    if not any(v in comando for v in VERBOS_QUE_MEXEM_EM_ARQUIVO):\n'
        '        return set()\n'
        '    achados = set()\n'
        '    for pedaco in CAMINHO_NO_COMANDO.findall(comando):\n'
        '        limpo = pedaco.strip("\'\\"")\n'
        '        if not limpo or limpo.startswith("-"):\n'
        '            continue\n'
        '        achados.add(str((raiz / limpo).resolve()))\n'
        '        achados.add(str(raiz / limpo))\n'
        '    return achados\n'
        '\n'
        '\n'
        'def _o_caminho_da_linha(raiz: Path, linha: str) -> str:\n'
        '    return str(raiz / linha[3:].strip().strip(\'"\'))\n'
        '\n'
        '\n'
        'def sujeira_desta_sessao_e_herdada(raiz: Path, abertura, entrada=None,\n'
        '                                   agora=None, lar=None) -> tuple:\n'
        '    suja = linhas_da_arvore_suja(raiz)\n'
        '    herdada = [l for l in suja\n'
        '               if modificado_antes_da_abertura(raiz, l, abertura)]\n'
        '    minha = [l for l in suja if l not in herdada]\n'
        '    if entrada is None:\n'
        '        return minha, herdada\n'
        '    lar = Path.home() if lar is None else lar\n'
        '    pasta = lar / PASTA_DOS_TRANSCRITOS / str(raiz).replace(os.sep, "-")\n'
        '    agora = time.time() if agora is None else agora\n'
        '    vizinha = sessoes_vivas_ao_lado(\n'
        '        pasta, str(entrada.get(CHAVE_DA_SESSAO) or ""), agora)\n'
        '    if not vizinha:\n'
        '        return minha, herdada\n'
        '    escritos = arquivos_que_esta_sessao_escreveu(\n'
        '        entrada.get(CHAVE_DO_TRANSCRITO), raiz)\n'
        '    if not escritos:\n'
        '        return minha, herdada\n'
        '    alheia = [l for l in minha if _o_caminho_da_linha(raiz, l) not in escritos]\n'
        '    return [l for l in minha if l not in alheia], herdada + alheia\n'
        '\n'
        '\n'
        'def pedido_mesclado_que_ja_contem(raiz: Path, principal: str,\n'
        '                                  integracao: str, adiante: list) -> bool:\n'
        '    montado = [parte.format(principal, integracao)\n'
        '               for parte in COMANDO_DO_PEDIDO_MESCLADO]\n'
        '    resposta = responde(montado, raiz, TEMPO_DA_REDE)\n'
        '    if resposta is NAO_MEDIDO or resposta[0] != 0 or not resposta[1]:\n'
        '        return False\n'
        '    mescla = resposta[1].split()[0]\n'
        '    for linha in adiante:\n'
        '        commit = linha.split()[0] if linha.split() else ""\n'
        '        if not commit:\n'
        '            continue\n'
        '        verificado = responde(\n'
        '            [p.format(commit, mescla) for p in COMANDO_DO_COMMIT_QUE_CONTEM],\n'
        '            raiz, TEMPO_DO_GIT)\n'
        '        if verificado is NAO_MEDIDO or verificado[0] != 0:\n'
        '            return False\n'
        '    return True\n'
        '\n'
        '\n'
        'def sobra_fora_da_branch_de_entrega(raiz: Path) -> str:\n'
        '    if not (raiz / INSTRUMENTO_DA_ENTREGA).is_file():\n'
        '        return ""\n'
        '    resposta = responde(\n'
        '        [sys.executable, INSTRUMENTO_DA_ENTREGA, BANDEIRA_DA_ENTREGA],\n'
        '        raiz, TEMPO_DO_GIT)\n'
        '    if resposta is NAO_MEDIDO or resposta[0] == 0:\n'
        '        return ""\n'
        '    return resposta[1]\n'
        '\n'
        '\n'
        'def commits_da_integracao_fora_da_principal(raiz: Path, principal: str,\n'
        '                                            integracao: str):\n'
        '    if not principal or not integracao:\n'
        '        return NAO_MEDIDO\n'
        '    responde([parte.format(principal, integracao)\n'
        '              for parte in COMANDO_DE_BUSCA_NO_REMOTO], raiz, TEMPO_DA_REDE)\n'
        '    comando = [parte.format(ESPELHO_NO_REMOTO.format(principal),\n'
        '                            ESPELHO_NO_REMOTO.format(integracao))\n'
        '               for parte in COMANDO_DO_QUE_A_PRINCIPAL_NAO_TEM]\n'
        '    resposta = responde(comando, raiz, TEMPO_DO_GIT)\n'
        '    if resposta is NAO_MEDIDO or resposta[0] != 0:\n'
        '        return NAO_MEDIDO\n'
        '    return [l for l in resposta[1].split("\\n") if l.strip()]\n'
        '\n'
        '\n'
        'def commits_desta_sessao(raiz: Path, principal: str, integracao: str,\n'
        '                         abertura, adiante: list) -> list:\n'
        '    if abertura is None or not adiante:\n'
        '        return list(adiante)\n'
        '    comando = [parte.format(ESPELHO_NO_REMOTO.format(principal),\n'
        '                            ESPELHO_NO_REMOTO.format(integracao),\n'
        '                            int(abertura))\n'
        '               for parte in COMANDO_DO_QUE_ESTA_SESSAO_ACRESCENTOU]\n'
        '    resposta = responde(comando, raiz, TEMPO_DO_GIT)\n'
        '    if resposta is NAO_MEDIDO or resposta[0] != 0:\n'
        '        return list(adiante)\n'
        '    return [l for l in resposta[1].split("\\n") if l.strip()]\n'
        '\n'
        '\n'
        'def ha_pedido_de_incorporacao_aberto(raiz: Path, principal: str,\n'
        '                                     integracao: str):\n'
        '    comando = [parte.format(principal, integracao)\n'
        '               for parte in COMANDO_DO_PEDIDO_ABERTO]\n'
        '    resposta = responde(comando, raiz, TEMPO_DA_REDE)\n'
        '    if resposta is NAO_MEDIDO or resposta[0] != 0:\n'
        '        return NAO_MEDIDO\n'
        '    try:\n'
        '        return int(resposta[1]) > 0\n'
        '    except ValueError:\n'
        '        return NAO_MEDIDO\n'
        '\n'
        '\n'
        'def resposta_limpa(comando: list, raiz: Path, tempo: int) -> str:\n'
        '    resposta = responde(comando, raiz, tempo)\n'
        '    if resposta is NAO_MEDIDO or resposta[0] != 0:\n'
        '        return ""\n'
        '    return resposta[1]\n'
        '\n'
        '\n'
        'def chegou_ao_repositorio_duravel(raiz: Path, branch: str):\n'
        '    if not branch:\n'
        '        return NAO_MEDIDO\n'
        '    aqui = resposta_limpa(COMANDO_DO_COMMIT_DA_ARVORE, raiz, TEMPO_DO_GIT)\n'
        '    comando = [parte.format(branch) for parte in COMANDO_DA_BRANCH_NO_DURAVEL]\n'
        '    resposta = responde(comando, raiz, TEMPO_DA_REDE)\n'
        '    if not aqui or resposta is NAO_MEDIDO or resposta[0] != 0:\n'
        '        return NAO_MEDIDO\n'
        '    la = resposta[1].split()\n'
        '    return bool(la) and la[0] == aqui\n'
        '\n'
        '\n'
        'def etapa_em_curso() -> str:\n'
        '    return os.environ.get(MARCA_DE_ETAPA_NO_AMBIENTE, "").strip()\n'
        '\n'
        '\n'
        'def _ha_destino_declarado(raiz: Path, principal: str, integracao: str,\n'
        '                          adiante: list):\n'
        '    aberto = ha_pedido_de_incorporacao_aberto(raiz, principal, integracao)\n'
        '    if aberto is True:\n'
        '        return True\n'
        '    if pedido_mesclado_que_ja_contem(raiz, principal, integracao, adiante):\n'
        '        return True\n'
        '    return aberto\n'
        '\n'
        '\n'
        'def medir(raiz: Path, abertura=None, entrada=None) -> dict:\n'
        '    suja, herdada = sujeira_desta_sessao_e_herdada(raiz, abertura, entrada)\n'
        '    nao_julgada = linhas_que_a_camada_nao_julga(raiz)\n'
        '    etapa = etapa_em_curso()\n'
        '    if etapa:\n'
        '        branch = resposta_limpa(COMANDO_DA_BRANCH_DA_ARVORE, raiz, TEMPO_DO_GIT)\n'
        '        return {\n'
        '            "etapa": etapa,\n'
        '            "suja": suja,\n'
        '            "herdada": herdada,\n'
        '            "nao_julgada": nao_julgada,\n'
        '            "branch": branch,\n'
        '            "duravel": chegou_ao_repositorio_duravel(raiz, branch),\n'
        '        }\n'
        '    principal = sorted(branches_por_incorporacao(raiz))\n'
        '    principal = principal[0] if principal else ""\n'
        '    integracao = branch_de_integracao(raiz)\n'
        '    tudo = commits_da_integracao_fora_da_principal(\n'
        '        raiz, principal, integracao)\n'
        '    if tudo is NAO_MEDIDO:\n'
        '        return {\n'
        '            "etapa": "", "suja": suja, "herdada": herdada,\n'
        '            "nao_julgada": nao_julgada,\n'
        '            "sobra": sobra_fora_da_branch_de_entrega(raiz),\n'
        '            "principal": principal, "integracao": integracao,\n'
        '            "adiante": NAO_MEDIDO, "herdados": [], "pedido": NAO_MEDIDO,\n'
        '        }\n'
        '    desta = (commits_desta_sessao(raiz, principal, integracao, abertura, tudo)\n'
        '             if tudo else [])\n'
        '    return {\n'
        '        "etapa": "",\n'
        '        "suja": suja,\n'
        '        "herdada": herdada,\n'
        '        "nao_julgada": nao_julgada,\n'
        '        "sobra": sobra_fora_da_branch_de_entrega(raiz),\n'
        '        "principal": principal,\n'
        '        "integracao": integracao,\n'
        '        "adiante": desta,\n'
        '        "herdados": [l for l in tudo if l not in desta],\n'
        '        "pedido": (_ha_destino_declarado(raiz, principal, integracao, tudo)\n'
        '                   if tudo else NAO_MEDIDO),\n'
        '    }\n'
        '\n'
        '\n'
        'def primeiras_linhas(linhas: list) -> str:\n'
        '    return "\\n".join(f"  {l}" for l in linhas[:TETO_DE_LINHAS])\n'
        '\n'
        '\n'
        'def cobrancas(estado: dict) -> list:\n'
        '    cobradas = []\n'
        '    if estado.get("suja"):\n'
        '        cobradas.append(COBRA_ARVORE_SUJA.format(\n'
        '            len(estado["suja"]), primeiras_linhas(estado["suja"])))\n'
        '    if estado.get("herdada"):\n'
        '        cobradas.append(COBRA_SUJEIRA_HERDADA.format(\n'
        '            len(estado["herdada"]), primeiras_linhas(estado["herdada"])))\n'
        '    if estado.get("nao_julgada"):\n'
        '        cobradas.append(COBRA_SUJEIRA_QUE_A_CAMADA_NAO_JULGA.format(\n'
        '            len(estado["nao_julgada"]),\n'
        '            primeiras_linhas(estado["nao_julgada"])))\n'
        '    if estado.get("etapa"):\n'
        '        if estado.get("duravel") is NAO_MEDIDO:\n'
        '            cobradas.append(COBRA_DURAVEL_NAO_MEDIDO.format(\n'
        '                estado.get("branch")))\n'
        '        elif not estado["duravel"]:\n'
        '            cobradas.append(COBRA_FORA_DO_REPOSITORIO_DURAVEL.format(\n'
        '                estado.get("branch")))\n'
        '        return cobradas\n'
        '    if estado.get("sobra"):\n'
        '        cobradas.append(COBRA_SOBRA_DA_BRANCH.format(\n'
        '            INSTRUMENTO_DA_ENTREGA, BANDEIRA_DA_ENTREGA, estado["sobra"]))\n'
        '    adiante = estado.get("adiante")\n'
        '    if adiante:\n'
        '        if estado.get("pedido") is False:\n'
        '            cobradas.append(COBRA_INTEGRACAO_SEM_PEDIDO.format(\n'
        '                estado.get("integracao"), len(adiante),\n'
        '                estado.get("principal"), primeiras_linhas(adiante)))\n'
        '        elif estado.get("pedido") is NAO_MEDIDO:\n'
        '            cobradas.append(COBRA_PEDIDO_NAO_MEDIDO.format(\n'
        '                estado.get("integracao"), len(adiante),\n'
        '                estado.get("principal")))\n'
        '    return cobradas\n'
        '\n'
        '\n'
        'def relato(estado: dict) -> list:\n'
        '    herdados = estado.get("herdados")\n'
        '    if not herdados or estado.get("pedido") is True:\n'
        '        return []\n'
        '    return [RELATA_HERDADO.format(estado.get("integracao"), len(herdados),\n'
        '                                  estado.get("principal"),\n'
        '                                  primeiras_linhas(herdados))]\n'
        '\n'
        '\n'
        'def decisao(entrada: dict, raiz: Path):\n'
        '    if entrada.get("stop_hook_active"):\n'
        '        return "", ""\n'
        '    estado = medir(raiz, abertura_da_sessao(entrada), entrada)\n'
        '    cobradas = cobrancas(estado)\n'
        '    if not cobradas:\n'
        '        return "", "\\n\\n".join(relato(estado))\n'
        '    return "\\n\\n".join(\n'
        '        [ABERTURA_DA_COBRANCA, *cobradas, FECHAMENTO_DA_COBRANCA]), ""\n'
        '\n'
        '\n'
        'def main() -> int:\n'
        '    try:\n'
        '        entrada = json.load(sys.stdin)\n'
        '        if not isinstance(entrada, dict):\n'
        '            return SILENCIO\n'
        '        motivo, dito = decisao(entrada, raiz_do_projeto_nunca_o_cwd())\n'
        '        if not motivo:\n'
        '            if dito:\n'
        '                print(json.dumps({"systemMessage": dito},\n'
        '                                 ensure_ascii=False))\n'
        '            return SILENCIO\n'
        '    except Exception:\n'
        '        return FALHA_ABERTA\n'
        '\n'
        '    print(json.dumps({"decision": DECISAO_DE_BLOQUEAR, "reason": motivo,\n'
        '                      "hookSpecificOutput": {\n'
        '                          "hookEventName": EVENTO_DE_PARADA}},\n'
        '                     ensure_ascii=False))\n'
        '    return COBRANCA_ENTREGUE\n'
        '\n'
        '\n'
        'ARVORE_LIMPA = {"etapa": "", "suja": [], "sobra": "", "principal": "main",\n'
        '                "integracao": "homolog", "adiante": [], "herdados": [],\n'
        '                "pedido": NAO_MEDIDO}\n'
        'DENTRO_DA_ETAPA = {"etapa": "trabalhar", "suja": [],\n'
        '                   "branch": "issue/1-algo", "duravel": True}\n'
        '\n'
        '\n'
        'def com(**mudanca) -> dict:\n'
        '    return {**ARVORE_LIMPA, **mudanca}\n'
        '\n'
        '\n'
        'def na_etapa(**mudanca) -> dict:\n'
        '    return {**DENTRO_DA_ETAPA, **mudanca}\n'
        '\n'
