        '         and "`conhecimento/`" in FECHAMENTO_DA_COBRANCA\n'
        '         and "nada fica sem destino" in FECHAMENTO_DA_COBRANCA)\n'
        '\n'
        '    falhas += [FALHA_COMPORTAMENTO.format(rotulo)\n'
