            '\n'
            'def _valor_como_o_source_le(valor: str) -> str:\n'
            '    entre_aspas = (len(valor) >= 2 and valor[0] == valor[-1]\n'
            '                   and valor[0] in "\\"\'")\n'
            '    if entre_aspas:\n'
            '        return valor[1:-1]\n'
            '    return re.split(r"\\s+#", valor, maxsplit=1)[0].strip()\n'
            '\n'
            '\n'
            'def _acrescentar_local_bin_no_fim(ambiente: dict) -> None:\n'
            '    local_bin = str(Path.home() / ".local" / "bin")\n'
