            '\n'
            '\n'
            'class TempoEstourado(Exception):\n'
            '    def __init__(self, tempo):\n'
            '        super().__init__(ERRO_TEMPO_ESTOURADO.format(tempo))\n'
            '        self.tempo = tempo\n'
            '\n'
            '\n'
            'def _resumo_do_evento(dado: dict) -> str:\n'
            '    tipo = dado.get("type")\n'
            '    if tipo == "assistant":\n'
            '        partes = []\n'
            '        for bloco in dado.get("message", {}).get("content", []):\n'
            '            if bloco.get("type") == "tool_use":\n'
            '                partes.append(_ferramenta_com_pista(bloco))\n'
            '            elif bloco.get("type") == "text":\n'
            '                partes.append(RESUMO_RESPONDE)\n'
            '        return " · ".join(partes)\n'
            '    if tipo == "result":\n'
            '        return RESUMO_FIM_DO_FLUXO.format(subtipo=dado.get("subtype", "?"),\n'
            '                                          turnos=dado.get("num_turns", "?"))\n'
            '    if tipo == "system" and dado.get("subtype") == "init":\n'
            '        return RESUMO_SESSAO_ABERTA\n'
            '    return ""\n'
            '\n'
            '\n'
            'def _ferramenta_com_pista(bloco: dict) -> str:\n'
            '    entrada = bloco.get("input") or {}\n'
            '    pista = (entrada.get("command") or entrada.get("file_path")\n'
            '             or entrada.get("pattern") or entrada.get("path") or "")\n'
            '    pista = _uma_linha(pista)[:LIMITE_DA_PISTA]\n'
            '    return f"{bloco[\'name\']}{f\' {pista}\' if pista else \'\'}"\n'
            '\n'
            '\n'
            'def _sessao_com_retomada(etapa, *, cwd, ambiente, log, rotulo):\n'
            '    tempo = etapa.get("tempo-limite", TEMPO_SESSAO)\n'
            '    entrada = _prompt_da_sessao(etapa, cwd)\n'
            '    retomar, ditos = "", []\n'
            '    for tentativa in range(RETOMADAS + 1):\n'
            '        codigo, saida, erro, marcas = _rodar_sessao_em_fluxo(\n'
            '            _comando_sessao(etapa, cwd, retomar), cwd=cwd, env=ambiente,\n'
            '            entrada=entrada, tempo=tempo, log=log,\n'
            '            rotulo=rotulo + (SUFIXO_DA_RETOMADA.format(tentativa)\n'
            '                             if tentativa else ""))\n'
            '        ditos += marcas.get("ditos", [])\n'
            '        marcas["ditos"] = ditos\n'
            '        if (espera := _espera_do_limite(saida, marcas.get("limite"))):\n'
            '            _dormir_ate_a_janela_abrir(espera, etapa, rotulo)\n'
            '            retomar = marcas.get("sessao") or retomar\n'
            '            entrada = PEDIDO_DE_FECHO if retomar else entrada\n'
            '            continue\n'
            '        if not _bateu_no_teto(saida) or tentativa == RETOMADAS:\n'
            '            return codigo, saida, erro, marcas\n'
            '        if not marcas.get("sessao"):\n'
            '            print(LOG_TETO_SEM_SESSAO.format(rotulo), flush=True)\n'
            '            return codigo, saida, erro, marcas\n'
            '        retomar, entrada = marcas["sessao"], PEDIDO_DE_FECHO\n'
            '        print(LOG_RETOMANDO_NO_TETO.format(rotulo=rotulo, vez=tentativa + 1,\n'
            '                                           teto=RETOMADAS), flush=True)\n'
            '    return codigo, saida, erro, marcas\n'
            '\n'
            '\n'
            'def _dormir_ate_a_janela_abrir(espera: int, etapa: dict, rotulo: str) -> None:\n'
            '    volta = time.strftime("%H:%M", time.localtime(time.time() + espera))\n'
            '    print(LOG_LIMITE_DE_USO.format(rotulo=rotulo, volta=volta,\n'
            '                                   minutos=espera // 60), flush=True)\n'
            '    if _EM_CURSO:\n'
            '        gravar_estado(_EM_CURSO["dir_base"], _EM_CURSO["trabalho"],\n'
            '                      "dormindo", etapa=etapa["nome"], ate=volta,\n'
            '                      porque=PORQUE_DORMINDO, issue=_EM_CURSO.get("issue"))\n'
            '    time.sleep(espera)\n'
            '    if _EM_CURSO:\n'
            '        gravar_estado(_EM_CURSO["dir_base"], _EM_CURSO["trabalho"],\n'
            '                      "rodando", etapa=etapa["nome"],\n'
            '                      issue=_EM_CURSO.get("issue"))\n'
            '\n'
            '\n'
            'def _resultado_da_sessao(saida: str):\n'
            '    try:\n'
            '        inicio = saida.find("{")\n'
            '        return json.loads(saida[inicio:saida.rfind("}") + 1])\n'
            '    except (ValueError, json.JSONDecodeError):\n'
            '        return {}\n'
            '\n'
            '\n'
            'def _espera_do_limite(saida: str, limite: dict | None) -> int:\n'
            '    dado = _resultado_da_sessao(saida)\n'
            '    subtipo = str(dado.get("subtype") or "")\n'
            '    if subtipo == SUBTIPO_SUCESSO:\n'
            '        return 0\n'
            '    texto = f"{subtipo} {dado.get(\'result\', \'\')}".lower()\n'
            '    bloqueado = bool(PAREDE_DE_USO.search(texto))\n'
            '    if isinstance(limite, dict) \\\n'
            '            and limite.get("status") not in STATUS_SEM_PAREDE:\n'
            '        bloqueado = True\n'
            '    if not bloqueado:\n'
            '        return 0\n'
            '    volta = (limite or {}).get("resetsAt")\n'
            '    if not isinstance(volta, (int, float)):\n'
            '        return ESPERA_SEM_HORA_DECLARADA_S\n'
            '    return max(ESPERA_MINIMA_S, min(ESPERA_MAXIMA_S,\n'
            '                                    int(volta - time.time())\n'
            '                                    + MARGEM_DA_ESPERA_S))\n'
            '\n'
            '\n'
            'def _bateu_no_teto(saida: str) -> bool:\n'
            '    return _resultado_da_sessao(saida).get("subtype") == SUBTIPO_TETO_DE_TURNOS\n'
            '\n'
            '\n'
            'def _rodar_sessao_em_fluxo(comando, *, cwd, env, entrada, tempo, log, rotulo):\n'
            '    with tempfile.TemporaryFile("w+", encoding="utf-8",\n'
            '                                errors="replace") as ferro:\n'
            '        processo = subprocess.Popen(\n'
            '            comando, shell=False, cwd=cwd, env=env,\n'
            '            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=ferro,\n'
            '            bufsize=0, start_new_session=True)\n'
            '        _alimentar_em_paralelo(processo, entrada)\n'
            '        colhido = _colher_o_fluxo(processo, tempo=tempo, log=log,\n'
            '                                  rotulo=rotulo)\n'
            '        processo.wait()\n'
            '        ferro.seek(0)\n'
            '        erro = ferro.read()\n'
            '    return (processo.returncode,\n'
            '            colhido["resultado"] or "".join(colhido["linhas"]), erro,\n'
            '            {"sessao": colhido["sessao"], "ditos": colhido["ditos"],\n'
            '             "limite": colhido["limite"]})\n'
            '\n'
            '\n'
            'def _alimentar_em_paralelo(processo, entrada: str) -> None:\n'
            '    def alimentar():\n'
            '        with contextlib.suppress(OSError, ValueError):\n'
            '            processo.stdin.write(entrada.encode(CODIFICACAO_DO_FLUXO))\n'
            '            processo.stdin.close()\n'
            '\n'
            '    threading.Thread(target=alimentar, daemon=True).start()\n'
            '\n'
            '\n'
            'def _linhas_do_pedaco(sobra: bytes, pedaco: bytes):\n'
            '    sobra += pedaco\n'
            '    *inteiras, sobra = sobra.split(QUEBRA_DE_LINHA)\n'
            '    return sobra, [(linha + QUEBRA_DE_LINHA).decode(CODIFICACAO_DO_FLUXO,\n'
            '                                                    errors="replace")\n'
            '                   for linha in inteiras]\n'
            '\n'
            '\n'
            'def _colher_o_fluxo(processo, *, tempo, log, rotulo) -> dict:\n'
            '    fim = time.monotonic() + tempo\n'
            '    colhido = {"resultado": "", "linhas": [], "sessao": "", "ditos": [],\n'
            '               "limite": None}\n'
            '    sobra = b""\n'
            '    with log.open("w", encoding="utf-8") as diario:\n'
            '        try:\n'
            '            while True:\n'
            '                restante = fim - time.monotonic()\n'
            '                if restante <= 0:\n'
            '                    raise TempoEstourado(tempo)\n'
            '                pronto, _, _ = select.select([processo.stdout], [], [],\n'
            '                                             min(restante, ESPIADA_S))\n'
            '                if not pronto:\n'
            '                    if processo.poll() is not None:\n'
            '                        break\n'
            '                    continue\n'
            '                pedaco = os.read(processo.stdout.fileno(), PEDACO_DO_FLUXO)\n'
            '                if not pedaco:\n'
            '                    break\n'
            '                sobra, linhas = _linhas_do_pedaco(sobra, pedaco)\n'
            '                for linha in linhas:\n'
            '                    diario.write(linha)\n'
            '                    diario.flush()\n'
            '                    colhido["linhas"].append(linha)\n'
            '                    try:\n'
            '                        dado = json.loads(linha)\n'
            '                    except json.JSONDecodeError:\n'
            '                        continue\n'
            '                    _guardar_o_que_importa(dado, linha, colhido)\n'
            '                    if (resumo := _resumo_do_evento(dado)):\n'
            '                        decorrido = int(tempo - (fim - time.monotonic()))\n'
            '                        print(LOG_ANDAMENTO_DA_SESSAO.format(\n'
            '                            minutos=decorrido // 60, segundos=decorrido % 60,\n'
            '                            rotulo=rotulo, resumo=resumo), flush=True)\n'
            '        except TempoEstourado:\n'
            '            _matar_grupo(processo)\n'
            '            raise\n'
            '        finally:\n'
            '            processo.stdout.close()\n'
            '    return colhido\n'
            '\n'
            '\n'
            'def _guardar_o_que_importa(dado: dict, linha: str, colhido: dict) -> None:\n'
            '    if dado.get("type") == "rate_limit_event":\n'
            '        colhido["limite"] = dado.get("rate_limit_info") or colhido["limite"]\n'
            '    if dado.get("session_id") and not colhido["sessao"]:\n'
            '        colhido["sessao"] = dado["session_id"]\n'
            '    if dado.get("type") == "result":\n'
            '        colhido["resultado"] = linha.strip()\n'
            '    if dado.get("type") == "assistant":\n'
            '        for bloco in dado.get("message", {}).get("content", []):\n'
            '            if bloco.get("type") == "text" and bloco.get("text"):\n'
            '                colhido["ditos"].append(bloco["text"].strip())\n'
            '\n'
            '\n'
            'def _matar_grupo(processo) -> None:\n'
            '    try:\n'
            '        os.killpg(os.getpgid(processo.pid), signal.SIGKILL)\n'
            '    except (ProcessLookupError, PermissionError):\n'
            '        pass\n'
            '    processo.wait()\n'
            '\n'
            '\n'
            '_PROCESSOS_DA_VEZ = set()\n'
            '\n'
            '\n'
            'def _instalar_a_parada_a_pedido(fechar, trabalho, marca_da_vez):\n'
            '    def tratador(*_):\n'
            '        for vivo in list(_PROCESSOS_DA_VEZ):\n'
            '            _matar_grupo(vivo)\n'
            '        fechar("parada", etapa=marca_da_vez[0] or None,\n'
            '               texto=ISSUE_PARADA_A_PEDIDO.format(\n'
            '                   etapa=marca_da_vez[0] or "nenhuma ainda",\n'
            '                   trabalho=trabalho))\n'
            '        os._exit(EXIT_PAROU_NUM_PARA)\n'
            '    return signal.signal(signal.SIGTERM, tratador)\n'
            '\n'
            '\n'
            'def _rodar_processo(comando, *, shell, cwd, env, entrada, tempo):\n'
            '    processo = subprocess.Popen(\n'
            '        comando, shell=shell, cwd=cwd, env=env,\n'
            '        stdin=subprocess.PIPE if entrada is not None else subprocess.DEVNULL,\n'
            '        stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,\n'
            '        start_new_session=True)\n'
            '    _PROCESSOS_DA_VEZ.add(processo)\n'
            '    try:\n'
            '        saida, erro = processo.communicate(entrada, timeout=tempo)\n'
            '    except subprocess.TimeoutExpired:\n'
            '        try:\n'
            '            os.killpg(os.getpgid(processo.pid), signal.SIGKILL)\n'
            '        except (ProcessLookupError, PermissionError):\n'
            '            pass\n'
            '        processo.wait()\n'
            '        raise TempoEstourado(tempo) from None\n'
            '    finally:\n'
            '        _PROCESSOS_DA_VEZ.discard(processo)\n'
            '    return processo.returncode, saida, erro\n'
            '\n'
            '\n'
