            '\n'
            '\n'
            'def _bloco_de_regras(cwd) -> str:\n'
            '    fonte = Path(cwd) / ARQUIVO_DAS_REGRAS\n'
            '    try:\n'
            '        texto = fonte.read_text(encoding="utf-8")\n'
            '    except (OSError, UnicodeDecodeError):\n'
            '        return ""\n'
            '    try:\n'
            '        regras = json.loads(texto)["regras"]\n'
