            '        return ""\n'
            '    return padrao.replace(MARCA_DO_NUMERO_NO_PADRAO, str(issue))\n'
            '\n'
            '\n'
            'def branch_fora_do_lugar(esperada: str, atual: str) -> bool:\n'
            '    if not esperada or not atual:\n'
            '        return False\n'
            '    molde = ".+".join(re.escape(pedaco)\n'
            '                      for pedaco in MARCA_LIVRE_NO_PADRAO.split(esperada))\n'
            '    return re.fullmatch(molde, atual) is None\n'
            '\n'
            '\n'
            'def cadastro_do_alvo(configuracao, ambiente) -> dict:\n'
            '    declarado = (ambiente or {}).get(VARIAVEL_DO_ALVO, "").strip()\n'
            '    if not declarado:\n'
            '        return {}\n'
            '    nome = Path(os.path.realpath(\n'
            '        Path(declarado).expanduser())).name.strip().lower()\n'
            '    projetos = (configuracao or {}).get("projetos") or {}\n'
            '    return next((p for p in projetos.values() if isinstance(p, dict)\n'
            '                 and (p.get("repositorio") or "").strip().lower() == nome),\n'
            '                {})\n'
            '\n'
            '\n'
            'def branches_do_alvo(configuracao, ambiente) -> dict:\n'
