            '    if faltas_declaradas:\n'
            '        lista = [FALTA_DA_ETAPA.format(etapa=etapa, falta=falta)\n'
            '                 for etapa, falta in faltas_declaradas]\n'
            '        print(LOG_PAROU_POR_FALTAS.format(\n'
            '            quantas=len(lista),\n'
            '            lista="\\n".join(ITEM_DA_FALTA.format(item) for item in lista)))\n'
            '        _fechar("parada", etapa=faltas_declaradas[0][0],\n'
            '                texto=ISSUE_EXECUCAO_PAROU_POR_FALTAS.format(\n'
            '                    quantas=len(lista),\n'
            '                    palavra="falta" if len(lista) == 1 else "faltas",\n'
            '                    faltas="\\n".join(RESUMO_ITEM.format(item)\n'
            '                                     for item in lista),\n'
            '                    trabalho=trabalho))\n'
            '        return EXIT_PAROU_NUM_PARA\n'
            '    custo = _custo_da_execucao(pasta)\n'
            '    print(LOG_EXECUCAO_COMPLETA.format(quantas=len(etapas), pasta=pasta,\n'
            '                                       custo=custo))\n'
            '    if roteiro.get("auditoria"):\n'
            '        auditar_ao_fim(pasta, cwd, ambiente)\n'
            '    _fechar("completa", texto=ISSUE_EXECUCAO_COMPLETA.format(\n'
            '        quantas=len(etapas),\n'
            '        palavra="etapa" if len(etapas) == 1 else "etapas",\n'
            '        trabalho=trabalho, custo=custo))\n'
            '    return EXIT_COMPLETA\n'
            '\n'
            '\n'
            'def _ler_evidencias(pasta: Path):\n'
            '    avisos, atuais = [], {}\n'
            '    paras, teto = 0, None\n'
            '    if not pasta.is_dir():\n'
            '        avisos.append(AVISO_DIRETORIO_INEXISTENTE.format(pasta))\n'
            '    for arquivo in sorted(pasta.glob("*.json")) if pasta.is_dir() else []:\n'
            '        try:\n'
            '            dado = json.loads(arquivo.read_text(encoding="utf-8"))\n'
            '            if not isinstance(dado, dict):\n'
            '                raise ValueError(ERRO_NAO_E_OBJETO_DE_EVIDENCIA)\n'
            '        except (OSError, ValueError):\n'
            '            avisos.append(\n'
            '                AVISO_EVIDENCIA_ILEGIVEL_NO_ANDAMENTO.format(arquivo.name))\n'
            '            paras += 1\n'
            '            continue\n'
            '        if dado.get("veredito") == "para":\n'
            '            paras += 1\n'
            '        ciclo = dado.get("ciclo", {})\n'
            '        if isinstance(ciclo, dict) and _inteiro_sao(ciclo.get("teto", 0)):\n'
            '            teto = ciclo["teto"]\n'
            '        pedacos = PADRAO_NOME_EVIDENCIA.match(arquivo.name)\n'
            '        if not pedacos:\n'
            '            avisos.append(AVISO_FORA_DO_PADRAO.format(arquivo.name))\n'
            '            continue\n'
            '        chave = (int(pedacos.group(1)), pedacos.group(2))\n'
            '        vez = int(pedacos.group(3))\n'
            '        if chave not in atuais or vez > atuais[chave][0]:\n'
            '            atuais[chave] = (vez, dado)\n'
            '    return atuais, paras, teto, avisos\n'
            '\n'
            '\n'
            'def _etapas_do_andamento(atuais: dict) -> list:\n'
            '    etapas = []\n'
            '    for ordem, nome in sorted(atuais):\n'
            '        _, dado = atuais[(ordem, nome)]\n'
            '        etapas.append({"ordem": ordem, "nome": nome,\n'
            '                       "veredito": dado.get("veredito"),\n'
            '                       "ciclo": dado.get("ciclo"),\n'
            '                       "faltas": dado.get("faltas", []),\n'
            '                       "proximo": dado.get("proximo"),\n'
            '                       "pergunta": dado.get("pergunta")})\n'
            '    return etapas\n'
            '\n'
            '\n'
            'def _git(cwd, *ordem, tempo=TEMPO_DO_GIT_LOCAL):\n'
            '    try:\n'
            '        return subprocess.run(["git", "-C", str(cwd), *ordem],\n'
            '                              capture_output=True, text=True, timeout=tempo)\n'
            '    except (OSError, subprocess.SubprocessError):\n'
            '        return None\n'
            '\n'
            '\n'
            'def _berro_do_git(feito) -> str:\n'
            '    if feito is None:\n'
            '        return GIT_MUDO\n'
            '    return _uma_linha(feito.stderr or feito.stdout)[:LIMITE_DO_ERRO_DO_GH]\n'
            '\n'
            '\n'
            'def _branch_da_evidencia(atuais: dict) -> str:\n'
            '    for (_, nome), (_, dado) in atuais.items():\n'
            '        if nome != ETAPA_QUE_ABRE_A_BRANCH:\n'
            '            continue\n'
            '        for prova in dado.get("provado") or []:\n'
            '            if isinstance(prova, dict) \\\n'
            '                    and prova.get("comando") == COMANDO_DA_BRANCH_ATUAL:\n'
            '                return str(prova.get("saida", "")).strip()\n'
            '    return ""\n'
            '\n'
            '\n'
            'def _branch_do_ambiente(pasta: Path, padrao) -> str:\n'
            '    if not padrao:\n'
            '        return ""\n'
            '    try:\n'
            '        dado = json.loads(\n'
            '            (pasta / ARQUIVO_DO_AMBIENTE).read_text(encoding="utf-8"))\n'
            '    except (OSError, ValueError):\n'
            '        return ""\n'
            '    variaveis = dado.get("variaveis") if isinstance(dado, dict) else None\n'
            '    if not isinstance(variaveis, dict):\n'
            '        return ""\n'
            '    nome = padrao.replace(\n'
            '        MARCA_DO_NUMERO_NO_PADRAO,\n'
            '        str(variaveis.get(VARIAVEL_DA_ISSUE, "")).strip()).replace(\n'
            '        MARCA_DO_ASSUNTO_NO_PADRAO,\n'
            '        str(variaveis.get(VARIAVEL_DO_ASSUNTO, "")).strip())\n'
            '    return "" if MARCA_LIVRE_NO_PADRAO.search(nome) else nome\n'
            '\n'
            '\n'
            'def _nao_medido(falta, provado=()) -> dict:\n'
            '    return {"chegou": False, "provado": list(provado), "faltas": [falta]}\n'
            '\n'
            '\n'
            'def destino_do_trabalho(cwd, branch, integracao) -> dict:\n'
            '    if not Path(cwd).is_dir():\n'
            '        return _nao_medido(FALTA_CWD_INUTILIZAVEL.format(cwd))\n'
            '    if not branch:\n'
            '        return _nao_medido(FALTA_SEM_BRANCH)\n'
            '    no_remoto = _git(cwd, "ls-remote", "--heads", REMOTO_GIT_PADRAO, branch,\n'
            '                     tempo=TEMPO_DO_GIT)\n'
            '    if no_remoto is None or no_remoto.returncode != 0:\n'
            '        return _nao_medido(FALTA_REMOTO_MUDO.format(\n'
            '            branch=branch, erro=_berro_do_git(no_remoto)))\n'
            '    if no_remoto.stdout.strip():\n'
            '        return {"chegou": True, "faltas": [], "provado": [\n'
            '            {"afirmacao": DESTINO_NO_REMOTO.format(branch=branch),\n'
            '             "comando": COMANDO_DA_BRANCH_NO_REMOTO.format(branch=branch),\n'
            '             "saida": no_remoto.stdout.strip()}]}\n'
            '    fora = {"afirmacao": BRANCH_FORA_DO_REMOTO.format(branch=branch),\n'
            '            "comando": COMANDO_DA_BRANCH_CONTADA.format(branch=branch),\n'
            '            "saida": "0"}\n'
            '    if not integracao:\n'
            '        return _nao_medido(FALTA_SEM_INTEGRACAO.format(\n'
            '            arquivo=ARQUIVO_EXECUTOR, cwd=cwd, branch=branch), [fora])\n'
            '    commit = _git(cwd, "rev-parse", "--verify", f"{branch}^{{commit}}")\n'
            '    if commit is None or commit.returncode != 0 or not commit.stdout.strip():\n'
            '        return _nao_medido(FALTA_SEM_O_COMMIT.format(\n'
            '            branch=branch, integracao=integracao), [fora])\n'
            '    sha = commit.stdout.strip()\n'
            '    contido = _git(cwd, "merge-base", "--is-ancestor", sha,\n'
            '                   f"{REMOTO_GIT_PADRAO}/{integracao}")\n'
            '    if contido is None or contido.returncode not in (0, 1):\n'
            '        return _nao_medido(FALTA_INTEGRACAO_MUDA.format(\n'
            '            sha=sha, integracao=integracao, erro=_berro_do_git(contido)),\n'
            '            [fora])\n'
            '    chegou = contido.returncode == 0\n'
            '    molde = DESTINO_NA_INTEGRACAO if chegou else COMMIT_FORA_DA_INTEGRACAO\n'
            '    return {"chegou": chegou,\n'
            '            "faltas": [] if chegou else [FALTA_SEM_DESTINO.format(\n'
            '                branch=branch, integracao=integracao)],\n'
            '            "provado": [fora, {\n'
            '                "afirmacao": molde.format(branch=branch, sha=sha,\n'
            '                                          integracao=integracao),\n'
            '                "comando": COMANDO_DO_COMMIT_NA_INTEGRACAO.format(\n'
            '                    sha=sha, integracao=integracao),\n'
            '                "saida": (CONTIDO_NA_INTEGRACAO if chegou\n'
            '                          else FORA_DA_INTEGRACAO)}]}\n'
            '\n'
            '\n'
            'def _estado_e_acao(etapas, sem_evidencia, paras, teto, trabalho, dir_base,\n'
            '                   pasta):\n'
            '    parado = next((e for e in etapas if e["veredito"] == "para"), None)\n'
            '    aguarda = next((e for e in etapas if e["veredito"] == "pergunta"), None)\n'
            '    if not etapas:\n'
            '        return "em-curso", ACAO_NADA_RODOU.format(trabalho=trabalho,\n'
            '                                                  dir_base=dir_base)\n'
            '    if teto is not None and paras >= teto:\n'
            '        return "parada", ACAO_TETO_ESGOTADO.format(teto=teto, pasta=pasta)\n'
            '    if parado:\n'
            '        return "parada", parado["proximo"] or ACAO_LEIA_A_EVIDENCIA.format(\n'
            '            etapa=parado["nome"], pasta=pasta)\n'
            '    if aguarda:\n'
            '        return "aguardando-aprovacao", aguarda["pergunta"] \\\n'
            '            or ACAO_LEIA_A_EVIDENCIA.format(etapa=aguarda["nome"],\n'
            '                                            pasta=pasta)\n'
            '    if sem_evidencia:\n'
            '        return "em-curso", ACAO_ETAPA_SEM_EVIDENCIA.format(\n'
            '            nomes=", ".join(sem_evidencia))\n'
            '    return "completa", ACAO_NADA_A_FAZER.format(pasta)\n'
            '\n'
            '\n'
            'def _com_o_estado_gravado(estado, acao, gravado):\n'
            '    if gravado and gravado.get("situacao") == "dormindo":\n'
            '        return "dormindo", ACAO_DORMINDO.format(\n'
            '            ate=gravado.get("ate", "?"),\n'
            '            porque=gravado.get("porque", "espera"),\n'
            '            etapa=gravado.get("etapa", "?"))\n'
            '    if gravado and gravado.get("situacao") == "aguardando-resposta" \\\n'
            '            and gravado.get("issue"):\n'
            '        return estado, ACAO_AGUARDANDO_RESPOSTA.format(\n'
            '            acao=acao, issue=gravado["issue"],\n'
            '            desde=gravado.get("desde", "?"))\n'
            '    if gravado and gravado.get("situacao") == "rodando" \\\n'
            '            and estado == "completa":\n'
            '        return "em-curso", ACAO_EXECUCAO_VIVA\n'
            '    return estado, acao\n'
            '\n'
            '\n'
            'def _com_o_destino_medido(estado, acao, cwd, atuais, pasta):\n'
            '    if estado != "completa":\n'
            '        return estado, acao, None\n'
            '    configuracao, _ = carregar_executor(cwd)\n'
            '    branch = (_branch_da_evidencia(atuais)\n'
            '              or _branch_do_ambiente(pasta, _campo(\n'
            '                  configuracao or {}, "branches.padrao_de_trabalho")))\n'
            '    destino = destino_do_trabalho(\n'
            '        cwd, branch, _campo(configuracao or {}, "branches.integracao"))\n'
            '    if destino["chegou"]:\n'
            '        return estado, acao, destino\n'
            '    return (ESTADO_SEM_DESTINO,\n'
            '            ACAO_DESTINO_NAO_MEDIDO.format(faltas="; ".join(destino["faltas"])),\n'
            '            destino)\n'
            '\n'
            '\n'
            'def andamento(trabalho, dir_base, cwd, etapas_do_roteiro=None) -> int:\n'
            '    pasta = Path(dir_base) / trabalho\n'
            '    atuais, paras, teto, avisos = _ler_evidencias(pasta)\n'
            '    etapas = _etapas_do_andamento(atuais)\n'
            '\n'
            '    sem_evidencia = []\n'
            '    if etapas_do_roteiro is not None:\n'
            '        com_evidencia = {nome for _, nome in atuais}\n'
            '        sem_evidencia = [e["nome"] for e in etapas_do_roteiro\n'
            '                         if e.get("ligada", True)\n'
            '                         and e["nome"] not in com_evidencia]\n'
            '\n'
            '    estado, acao = _estado_e_acao(etapas, sem_evidencia, paras, teto,\n'
            '                                  trabalho, dir_base, pasta)\n'
            '    gravado = ler_estado(dir_base, trabalho)\n'
            '    estado, acao = _com_o_estado_gravado(estado, acao, gravado)\n'
            '    estado, acao, destino = _com_o_destino_medido(estado, acao, cwd, atuais,\n'
            '                                                  pasta)\n'
            '\n'
            '    ultima_ordem = max((ordem for ordem, _ in atuais), default=0)\n'
            '    etapas = etapas + [\n'
            '        {"ordem": ultima_ordem + i + 1, "nome": nome, "veredito": None,\n'
            '         "ciclo": None, "faltas": [], "proximo": None, "pergunta": None}\n'
            '        for i, nome in enumerate(sem_evidencia)]\n'
            '\n'
            '    print(json.dumps({"trabalho": trabalho, "dir": dir_base,\n'
            '                      "estado": estado, "etapas": etapas, "paras": paras,\n'
            '                      "teto": teto, "avisos": avisos, "proxima_acao": acao,\n'
            '                      "gravado": gravado, "destino": destino},\n'
            '                     ensure_ascii=False, indent=2))\n'
            '    return EXIT_COMPLETA\n'
            '\n'
            '\n'
            'def _horas_desde(quando) -> float:\n'
            '    try:\n'
            '        desde = datetime.fromisoformat(quando)\n'
            '    except (TypeError, ValueError):\n'
            '        return 0.0\n'
            '    agora = datetime.now(desde.tzinfo)\n'
            '    return (agora - desde).total_seconds() / 3600\n'
            '\n'
            '\n'
            'def _comando_que_destrava(estado) -> str:\n'
            '    roteiro, cwd = estado.get("roteiro"), estado.get("cwd")\n'
            '    if not roteiro or not cwd:\n'
            '        return ""\n'
            '    return (f"python3 .agents/encadeador/encadeador.py executar "\n'
            '            f"--roteiro {roteiro} --trabalho {estado[\'trabalho\']} "\n'
            '            f"--dir {estado[\'dir\']} --cwd {cwd} --retomar")\n'
            '\n'
            '\n'
            'def _porque_esta_presa(estado) -> str:\n'
            '    situacao = estado.get("situacao")\n'
            '    if situacao == "aguardando-resposta":\n'
            '        if estado["horas"] > TETO_DA_ESPERA_H:\n'
            '            return RONDA_ESPERA_VENCIDA\n'
            '        return ""\n'
            '    if processo_vivo(estado.get("pid")):\n'
            '        return ""\n'
            '    if situacao == "rodando":\n'
            '        return RONDA_RODANDO_MORTO\n'
            '    if situacao == "dormindo":\n'
            '        ate = estado.get("ate")\n'
            '        if ate and _horas_desde(ate) > 0:\n'
            '            return RONDA_DORMINDO_VENCIDO.format(ate=ate)\n'
            '    return ""\n'
            '\n'
            '\n'
            'def _presas(dir_base) -> list:\n'
            '    achadas = []\n'
            '    for alvo in sorted(Path(dir_base).glob("*/" + ARQUIVO_ESTADO)):\n'
            '        try:\n'
            '            dado = json.loads(alvo.read_text(encoding="utf-8"))\n'
            '        except (OSError, ValueError):\n'
            '            continue\n'
            '        if not isinstance(dado, dict):\n'
            '            continue\n'
            '        dado["trabalho"] = alvo.parent.name\n'
            '        dado["dir"] = str(dir_base)\n'
            '        dado["horas"] = _horas_desde(dado.get("desde"))\n'
            '        porque = _porque_esta_presa(dado)\n'
            '        if porque:\n'
            '            achadas.append((dado, porque))\n'
            '    return achadas\n'
            '\n'
            '\n'
            'def ronda(dir_base) -> int:\n'
            '    achadas = _presas(dir_base)\n'
            '    if not achadas:\n'
            '        print(RONDA_LIMPA.format(dir=dir_base))\n'
            '        return EXIT_COMPLETA\n'
            '    print(RONDA_CABECA.format(teto=TETO_DA_ESPERA_H))\n'
            '    for estado, porque in achadas:\n'
            '        issue = estado.get("issue")\n'
            '        etapa = estado.get("etapa")\n'
            '        print(RONDA_LINHA.format(\n'
            '            trabalho=estado["trabalho"], situacao=estado.get("situacao"),\n'
            '            horas=f"{estado[\'horas\']:.1f}",\n'
            '            issue=f", issue {issue}" if issue else "",\n'
            '            etapa=f", etapa {etapa}" if etapa else "", porque=porque))\n'
            '        comando = _comando_que_destrava(estado)\n'
            '        print(RONDA_DESTRAVA.format(comando=comando) if comando\n'
            '              else RONDA_SEM_COMANDO)\n'
            '    return EXIT_PAROU_NUM_PARA\n'
            '\n'
            '\n'
            'def _ultima_evidencia(atuais: dict) -> dict:\n'
            '    if not atuais:\n'
            '        return {}\n'
            '    return atuais[max(atuais)][1]\n'
            '\n'
            '\n'
            'def _ciclo_legivel(dado: dict) -> str:\n'
            '    ciclo = dado.get("ciclo")\n'
            '    if not isinstance(ciclo, dict) or not _inteiro_sao(ciclo.get("i", 0)) \\\n'
            '            or not _inteiro_sao(ciclo.get("teto", 0)):\n'
            '        return SEM_CICLO\n'
            '    return CICLO_NA_FILA.format(i=ciclo["i"], teto=ciclo["teto"])\n'
            '\n'
            '\n'
            'def _espera_uma_pessoa(situacao: str, ultima: dict) -> bool:\n'
            '    return (situacao == "aguardando-resposta"\n'
            '            or ultima.get("veredito") == "pergunta")\n'
            '\n'
            '\n'
            'def _lugar_na_fila(dir_base, trabalho) -> dict:\n'
            '    pasta = Path(dir_base) / trabalho\n'
            '    atuais, _, _, _ = _ler_evidencias(pasta)\n'
            '    ultima = _ultima_evidencia(atuais)\n'
            '    gravado = ler_estado(dir_base, trabalho) or {}\n'
            '    situacao = gravado.get("situacao") or SEM_ESTADO\n'
            '    return {"trabalho": trabalho,\n'
            '            "issue": gravado.get("issue"),\n'
            '            "etapa": gravado.get("etapa") or ultima.get("etapa"),\n'
            '            "ciclo": _ciclo_legivel(ultima),\n'
            '            "situacao": situacao,\n'
            '            "espera_voce": _espera_uma_pessoa(situacao, ultima),\n'
            '            "desde": gravado.get("desde"),\n'
            '            "custo": _custo_da_execucao(pasta)}\n'
            '\n'
            '\n'
            'def _e_trabalho(pasta: Path) -> bool:\n'
            '    return pasta.is_dir() and (\n'
            '        (pasta / ARQUIVO_ESTADO).is_file()\n'
            '        or any(PADRAO_NOME_EVIDENCIA.match(q.name) for q in pasta.iterdir()))\n'
            '\n'
            '\n'
            'def _trabalhos_da_fila(dir_base) -> list:\n'
            '    raiz = Path(dir_base)\n'
            '    if not raiz.is_dir():\n'
            '        return []\n'
            '    return [_lugar_na_fila(dir_base, pasta.name)\n'
            '            for pasta in sorted(raiz.iterdir()) if _e_trabalho(pasta)]\n'
            '\n'
            '\n'
            'def _chave_da_fila(lugar: dict):\n'
            '    return (0 if lugar["espera_voce"]\n'
            '            else ORDEM_NA_FILA.get(lugar["situacao"], 1),\n'
            '            lugar["trabalho"])\n'
            '\n'
            '\n'
            'def _linha_da_fila(lugar: dict, nome: int) -> str:\n'
            '    horas = (HORAS_NA_FILA.format(_horas_desde(lugar["desde"]))\n'
            '             if lugar["desde"] else SEM_HORAS)\n'
            '    return FILA_LINHA.format(\n'
            '        marca=MARCA_DE_QUEM_ESPERA_VOCE if lugar["espera_voce"] else "",\n'
            '        largura=len(MARCA_DE_QUEM_ESPERA_VOCE),\n'
            '        trabalho=lugar["trabalho"], nome=nome,\n'
            '        issue=lugar["issue"] if lugar["issue"] is not None else SEM_ISSUE,\n'
            '        etapa=lugar["etapa"] or SEM_ETAPA, ciclo=lugar["ciclo"],\n'
            '        situacao=lugar["situacao"], horas=horas, custo=lugar["custo"])\n'
            '\n'
            '\n'
            'def issues_paradas_em_voce(configuracao) -> tuple:\n'
            '    repositorio = _campo(configuracao or {}, "issues.repositorio")\n'
            '    if not repositorio:\n'
            '        return [], BERRO_DA_FILA_SEM_REPOSITORIO\n'
            '    feito = _gh_na_conta_das_issues(\n'
            '        configuracao, ["issue", "list", "--repo", repositorio, "--state",\n'
            '                       "open", "--label", ETIQUETA_PARADO_EM_VOCE, "--json",\n'
